window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-98"]=[{"id":"set2-AtkUmZLZ","fingerprint":"771bfa3196b8f85e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele utilizării sistemului de digă în tratamentul endodontic?","options":[{"id":"A","text":"Elimină necesitatea unei reconstrucții coronare temporare în cazul dinților cu distrucții masive."},{"id":"B","text":"Reduce încărcarea cu microfloră orală a aerosolilor produși în timpul tratamentului."},{"id":"C","text":"Împiedică aspirarea sau ingestia corpilor străini."},{"id":"D","text":"Simplifică aplicarea în cazuri clinice dificile, precum molarii de minte."},{"id":"E","text":"Asigură o vizibilitate îmbunătățită a câmpului operator."}],"correct":["B","C","E"],"pages":[123],"source":"set-2"},{"id":"set2-ro2voJBL","fingerprint":"8e04a221fdeb787b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În care dintre următoarele situații este contraindicată aplicarea sistemului de digă?","options":[{"id":"A","text":"La un pacient cu alergie la nitril."},{"id":"B","text":"La un dinte cu o distrucție coronară importantă."},{"id":"C","text":"La un molar de minte."},{"id":"D","text":"La un dinte în malpoziție."},{"id":"E","text":"La un pacient care suferă de astm."}],"correct":["E"],"pages":[123],"source":"set-2"},{"id":"set2-zpbk_BfK","fingerprint":"be66f7ab422f9221","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații referitoare la componentele sistemului de digă sunt adevărate?","options":[{"id":"A","text":"Inelul sau arcul unei cleme de digă se plasează întotdeauna pe partea distală a dintelui."},{"id":"B","text":"Cleștele perforator de tip Ash realizează orificii cu diametre variabile."},{"id":"C","text":"Cleștele perforator de tip Ainsworth este capabil să realizeze orificii de diametre diferite în folie."},{"id":"D","text":"Cadrul pentru susținerea foliei este fabricat exclusiv din material plastic."},{"id":"E","text":"Folia de digă are o grosime cuprinsă între 0,15 și 0,35 mm."}],"correct":["A","C","E"],"pages":[123],"source":"set-2"},{"id":"set2-v6hy8VQq","fingerprint":"aa6645368bead35a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce instrumentar este recomandat pentru etapa de trepanare a camerei pulpare la nivelul smalțului?","options":[{"id":"A","text":"Freze diamantate sferice utilizate la viteză convențională."},{"id":"B","text":"Freze diamantate sferice utilizate la viteză înaltă."},{"id":"C","text":"Freze de piesă contraunghi la viteză convențională."},{"id":"D","text":"Freze diamantate cilindrice la viteză înaltă."},{"id":"E","text":"Inserturi ultrasonice pentru piesa contraunghi."}],"correct":["B"],"pages":[123],"source":"set-2"},{"id":"set2-mkeEDOoD","fingerprint":"eb3e227f71741753","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este rolul principal al frezelor diamantate sferice în prepararea cavității de acces?","options":[{"id":"A","text":"Localizarea orificiilor de intrare în canalele radiculare."},{"id":"B","text":"Trepanarea camerei pulpare, utilizând viteză înaltă în smalț și viteză convențională în dentină."},{"id":"C","text":"Îndepărtarea completă a tavanului camerei pulpare prin mișcări de lateralitate."},{"id":"D","text":"Verificarea îndepărtării complete a tavanului camerei pulpare prin palpare."},{"id":"E","text":"Finisarea pereților cavității de acces, protejând planșeul camerei pulpare de perforații."}],"correct":["B"],"pages":[124],"source":"set-2"},{"id":"set2-6gEzhNtl","fingerprint":"6cca6e8cfcf0ef51","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații referitoare la instrumentarul utilizat pentru prepararea cavității de acces sunt adevărate?","options":[{"id":"A","text":"Ansele (inserturile) ultrasonice sunt utilizate exclusiv pentru detectarea orificiilor de emergență ale canalelor radiculare."},{"id":"B","text":"Frezele diamantate sunt preferate celor din carbură de tungsten deoarece creează suprafețe mai netede și vibrează mai puțin."},{"id":"C","text":"Sonda Rhein (DG 16) este utilizată pentru a verifica dacă tavanul camerei pulpare a fost complet îndepărtat."},{"id":"D","text":"Pentru dinții cu o coroană înaltă, se recomandă utilizarea frezelor cu gât scurt."},{"id":"E","text":"Finisarea cavității de acces se realizează la viteză înaltă cu freze ce au un vârf inactiv pentru a preveni perforarea planșeului pulpar."}],"correct":["B","E"],"pages":[124],"source":"set-2"},{"id":"set2-WY1_CURv","fingerprint":"4327fa6b2fb6dbb4","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este utilitatea specifică a sondei Rhein sau DG 16 în cadrul tratamentului endodontic?","options":[{"id":"A","text":"Îndepărtarea controlată a dentinei și a calcificărilor din camera pulpară."},{"id":"B","text":"Estimarea lungimii de lucru pe o radiografie pre-operatorie."},{"id":"C","text":"Localizarea orificiilor de intrare în canalele radiculare și determinarea angulației acestora."},{"id":"D","text":"Controlul prin palpare al eliminării complete a tavanului camerei pulpare."},{"id":"E","text":"Realizarea unei treceri line între pereții cavității de acces și cei ai camerei pulpare."}],"correct":["C"],"pages":[124],"source":"set-2"},{"id":"set2-ZCO_8JZ7","fingerprint":"69867a4faaa9d74d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Conform standardizării ISO pentru instrumentele endodontice manuale, care dintre următoarele caracteristici dimensionale sunt corecte?","options":[{"id":"A","text":"Lungimea totală a ansamblului tijă și parte activă poate fi de 21 mm, 25 mm sau 31 mm."},{"id":"B","text":"Lungimea părții active este constantă, de 16 mm, indiferent de lungimea totală a instrumentului."},{"id":"C","text":"Diferența dintre diametrul la vârf și cel de la baza părții active este o valoare constantă de 0,32 mm."},{"id":"D","text":"Conicitatea instrumentelor endodontice manuale convenționale variază între 2% și 6%."},{"id":"E","text":"Partea activă are o lungime de 21 mm pentru dinții laterali."}],"correct":["A","B","C"],"pages":[124],"source":"set-2"},{"id":"set2-N0uBcADs","fingerprint":"b65d47af317014df","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce definește conicitatea ISO de 2% a instrumentelor endodontice manuale convenționale?","options":[{"id":"A","text":"Variația diametrului la vârf între 6 și 140 de sutimi de milimetru."},{"id":"B","text":"Materialul din care sunt confecționate, respectiv aliajul de oțel inoxidabil."},{"id":"C","text":"Lungimea standard de 16 mm a părții active a instrumentului."},{"id":"D","text":"Diferența constantă de 0,32 mm între diametrul la vârf și cel de la baza părții active."},{"id":"E","text":"Creșterea diametrului părții active cu 0,02 mm pentru fiecare milimetru de lungime, pornind de la vârf spre mâner."}],"correct":["E"],"pages":[124],"source":"set-2"},{"id":"set2-MX9RSx7p","fingerprint":"59c0f3287bbe6901","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile distinctive ale acelor Kerr de tip burghiu (reamer) și pilă (file)?","options":[{"id":"A","text":"Acele Kerr pilă (file) au o secțiune pătrată, ceea ce le conferă rezistență la torsiune și flexiune."},{"id":"B","text":"Acele Kerr burghiu (reamer) prezintă între 24 și 36 de spire."},{"id":"C","text":"Ambele tipuri de instrumente produc o lărgire concentrică în canalele radiculare curbe."},{"id":"D","text":"Acele Kerr burghiu (reamer) au o secțiune triunghiulară și sunt mai eficiente în îndepărtarea dentinei radiculare."},{"id":"E","text":"Acele Kerr pilă (file) sunt indicate pentru negocierea inițială a canalelor radiculare."}],"correct":["A","D","E"],"pages":[124],"source":"set-2"},{"id":"set2-0q5bUfkL","fingerprint":"b6354d5c17cd6793","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este corelația dintre forma pe secțiune a acelor Kerr clasice și funcționalitatea lor clinică?","options":[{"id":"A","text":"Forma de romb oferă rezistență la torsiune, în timp ce forma pătrată asigură o mai bună eliminare a detritusurilor."},{"id":"B","text":"Forma pătrată asigură o îndepărtare eficientă a dentinei, în timp ce forma triunghiulară oferă rezistență la torsiune."},{"id":"C","text":"Forma pătrată asigură rezistența la torsiune și flexiune, fiind indicată în negocierea inițială a canalelor, iar forma triunghiulară este mai eficientă în îndepărtarea dentinei."},{"id":"D","text":"Rol de electrod pentru ionoforeză și diatermie."},{"id":"E","text":"Ambele forme, pătrată și triunghiulară, au roluri identice, diferența fiind doar de producător."}],"correct":["C"],"pages":[125],"source":"set-2"},{"id":"set2-lCD3__9k","fingerprint":"c6524b591794d18a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele reprezintă accidente posibile în timpul preparării canalelor radiculare curbe cu instrumente manuale?","options":[{"id":"A","text":"Transportarea canalului."},{"id":"B","text":"Fenestrare."},{"id":"C","text":"Fracturarea instrumentului prin rotație."},{"id":"D","text":"Pistonarea unor paste medicamentoase în canal."},{"id":"E","text":"Crearea de praguri."}],"correct":["A","B","E"],"pages":[125],"source":"set-2"},{"id":"set2-lDJ1Hlpi","fingerprint":"d3546b7a730a1112","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce caracteristici distinctive prezintă acele K-Flex în comparație cu acele Kerr clasice?","options":[{"id":"A","text":"Au un număr de lame dublu față de alte instrumente."},{"id":"B","text":"O flexibilitate sporită, în special la diametre mari."},{"id":"C","text":"O secțiune transversală în formă de romb."},{"id":"D","text":"Lame asimetrice care favorizează eliminarea detritusurilor."},{"id":"E","text":"Un vârf rotunjit, inactiv, indicat în tehnica forțelor compensate."}],"correct":["B","C","D"],"pages":[125],"source":"set-2"},{"id":"set2-ZDsp3vkD","fingerprint":"feeb04f08311f094","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este mișcarea specifică pentru utilizarea acelor Hedström și ce manevră este strict interzisă?","options":[{"id":"A","text":"Toate mișcările (axiale și de rotație) sunt permise pentru a crește eficiența."},{"id":"B","text":"Mișcarea specifică este cea de periere circumferențială, iar pistonarea este interzisă."},{"id":"C","text":"Mișcarea specifică este rotația orară, iar mișcarea axială este interzisă."},{"id":"D","text":"Completarea lărgirii canalelor radiculare."},{"id":"E","text":"Mișcarea specifică este raclarea prin mișcări axiale de du-te vino, iar rotația este interzisă."}],"correct":["E"],"pages":[125],"source":"set-2"},{"id":"set2-Asss5Otv","fingerprint":"2cc8f02377ea8cd1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce caracteristici definitorii au acele S-file și Uni-file?","options":[{"id":"A","text":"Sunt active în rotație orară și inactive în sens antiorar."},{"id":"B","text":"Au un număr de lame dublu, ceea ce le crește rezistența mecanică."},{"id":"C","text":"Prezintă o secțiune transversală în formă de \"S\" cu elice dublă."},{"id":"D","text":"Sunt fabricate dintr-o tijă de oțel cu secțiune triunghiulară."},{"id":"E","text":"Elimină efectul de înșurubare specific acelor Hedström."}],"correct":["A","B","C","E"],"pages":[125],"source":"set-2"},{"id":"set2-DF2rEkpb","fingerprint":"c019fe2137116db7","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este scopul principal al utilizării frezelor de tip Gates-Glidden în tratamentul endodontic?","options":[{"id":"A","text":"Forma lor pe secțiune este cea a unei elice triple."},{"id":"B","text":"Efectuarea odontometriei electronice cu precizie maximă."},{"id":"C","text":"Lărgirea completă a treimii apicale a canalului radicular."},{"id":"D","text":"Dezobturarea canalelor radiculare umplute cu gutapercă."},{"id":"E","text":"Realizarea unei preevazări în treimea coronară pentru un acces direct spre apex."}],"correct":["E"],"pages":[125],"source":"set-2"},{"id":"set2-D3UUBKgK","fingerprint":"9c042b346413629c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele proprietăți sunt superioare la aliajul de nichel-titan față de oțelul inoxidabil, în contextul instrumentarului endodontic?","options":[{"id":"A","text":"Memorie elastică."},{"id":"B","text":"Biocompatibilitate."},{"id":"C","text":"Sunt folosite pentru cateterismul și lărgirea canalelor radiculare."},{"id":"D","text":"Flexibilitate."},{"id":"E","text":"Rezistență la coroziune."}],"correct":["B","D","E"],"pages":[125],"source":"set-2"},{"id":"set2-DgOgTTHe","fingerprint":"84d156abf7edebde","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Un instrument endodontic este descris ca fiind foarte activ, cu trei lame tăietoare opozante (elice triplă) și o capacitate de centrare superioară în canalele neregulate. Despre ce instrument este vorba?","options":[{"id":"A","text":"Acele K-Flex"},{"id":"B","text":"Frezele Gates-Glidden"},{"id":"C","text":"Acele S-file"},{"id":"D","text":"Acele Helifile"},{"id":"E","text":"Secțiunea transversală triunghiulară și vârful inactiv."}],"correct":["D"],"pages":[125],"source":"set-2"},{"id":"set2-Mf8oBe5F","fingerprint":"f8c7fae947a99b7c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt proprietățile aliajului de nichel-titan, superioare oțelului inoxidabil, menționate pentru realizarea instrumentarului endodontic?","options":[{"id":"A","text":"Biocompatibilitate"},{"id":"B","text":"Duritate crescută"},{"id":"C","text":"Rezistență la coroziune"},{"id":"D","text":"Elasticitate"},{"id":"E","text":"Flexibilitate"}],"correct":["A","C","D","E"],"pages":[126],"source":"set-2"},{"id":"set2-t-wjH9kT","fingerprint":"65c43bab770babed","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este compoziția aproximativă în greutate a aliajului de nichel-titan utilizat pentru instrumentarul endodontic?","options":[{"id":"A","text":"Circa 45% nichel și 55% titan"},{"id":"B","text":"Circa 55% titan și 45% oțel inoxidabil"},{"id":"C","text":"Circa 55% nichel și 45% titan"},{"id":"D","text":"Circa 90% nichel și 10% titan"},{"id":"E","text":"Circa 55% nichel și 45% oțel inoxidabil"}],"correct":["C"],"pages":[126],"source":"set-2"},{"id":"set2-PDOrm1cP","fingerprint":"b87c6888417a1c83","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce caracteristici definitorii prezintă conicitatea instrumentelor de nichel-titan?","options":[{"id":"A","text":"Este întotdeauna mai mică decât cea a instrumentelor din oțel."},{"id":"B","text":"Poate fi constantă sau variabilă de-a lungul părții active."},{"id":"C","text":"Permite reducerea numărului de instrumente necesare."},{"id":"D","text":"Este întotdeauna fixă, de 2%, pentru a asigura flexibilitatea."},{"id":"E","text":"Poate varia între 2% și 12-19%."}],"correct":["B","C","E"],"pages":[126],"source":"set-2"},{"id":"set2-htrWAOHn","fingerprint":"eba8910e92512897","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce reprezintă proprietatea de \"memorie a formei\" a instrumentelor de nichel-titan?","options":[{"id":"A","text":"Capacitatea de a reveni la forma inițială după curbare, fără a suferi deformări."},{"id":"B","text":"Capacitatea de a se deforma permanent pentru a se adapta la curbura canalului."},{"id":"C","text":"Capacitatea de a rezista la fractură la un cuplu ridicat."},{"id":"D","text":"Capacitatea de a memora ultima formă utilizată în canal."},{"id":"E","text":"Capacitatea de a-și schimba faza de la martensitică la austenitică la temperatura camerei."}],"correct":["A"],"pages":[126],"source":"set-2"},{"id":"set2-D4tGpngc","fingerprint":"d14f6fbfa9a3c166","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este viteza de rotație recomandată uzual pentru un instrument endodontic din aliaj Ni-Ti?","options":[{"id":"A","text":"Între 250 și 600 rotații/min"},{"id":"B","text":"Întotdeauna 300 rotații/min, indiferent de sistem"},{"id":"C","text":"Sub 100 rotații/min"},{"id":"D","text":"Între 100 și 1000 rotații/min"},{"id":"E","text":"Peste 1000 rotații/min"}],"correct":["A"],"pages":[126],"source":"set-2"},{"id":"set2-xn6J2zZR","fingerprint":"965ef223de290ad2","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform regulilor generale de utilizare, care este durata maximă de lucru la o singură introducere a unui instrument rotativ Ni-Ti în canalul radicular?","options":[{"id":"A","text":"Minimum 15 secunde pentru a asigura curățarea completă."},{"id":"B","text":"Nu trebuie să depășească 10 secunde sau 3 mișcări de introducere-extragere."},{"id":"C","text":"Maximum 2 secunde, pentru a evita supraîncălzirea."},{"id":"D","text":"Nu există o limită de timp specificată, depinzând de anatomia canalului."},{"id":"E","text":"Până la 30 de secunde, pentru o instrumentare eficientă."}],"correct":["B"],"pages":[126],"source":"set-2"},{"id":"set2-l5kuTCId","fingerprint":"2b940eb8f920bb51","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce acțiune preliminară este obligatorie înainte de utilizarea instrumentelor rotative de Ni-Ti într-un canal radicular?","options":[{"id":"A","text":"Irigarea abundentă a canalului cu ser fiziologic."},{"id":"B","text":"Realizarea unei radiografii retroalveolare de control."},{"id":"C","text":"Uscarea completă a canalului cu conuri de hârtie."},{"id":"D","text":"Aplicarea unui gel cu EDTA pentru a lubrifia canalul."},{"id":"E","text":"Verificarea permeabilității canalului cu un ac Kerr de 08 sau 10."}],"correct":["E"],"pages":[126],"source":"set-2"},{"id":"set2-rFMJcraa","fingerprint":"41f4375917ad12ac","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile fazelor distincte ale aliajului de nichel-titan în funcție de temperatură?","options":[{"id":"A","text":"La temperatură înaltă, aliajul se află în forma martensitică, fiind ductil."},{"id":"B","text":"Indiferent de temperatură, aliajul prezintă o combinație stabilă a ambelor faze."},{"id":"C","text":"La temperatură joasă, aliajul se află în forma austenitică, fiind rezistent."},{"id":"D","text":"La temperatură joasă, aliajul se află în forma martensitică, fiind ductil și foarte elastic."},{"id":"E","text":"La temperatură înaltă, aliajul se află în forma austenitică, fiind rezistent și stabil."}],"correct":["D","E"],"pages":[126],"source":"set-2"},{"id":"set2-EvY0AZaq","fingerprint":"8c8473a1c81d369d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce fenomen stă la baza supraelasticității aliajului de nichel-titan?","options":[{"id":"A","text":"Transformarea reversibilă dintre faza austenitică și cea martensitică."},{"id":"B","text":"Conținutul ridicat de nichel, de peste 55% din greutate."},{"id":"C","text":"Tratamentul termomecanic specific aplicat în timpul producției."},{"id":"D","text":"Adaptarea superioară la solicitarea mecanică fără creșterea tensiunii interne."},{"id":"E","text":"Flexibilitatea de 4 ori mai mare decât cea a oțelului."}],"correct":["A"],"pages":[126],"source":"set-2"},{"id":"set2-4jtMy_pD","fingerprint":"5dfcd24811269473","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile fazelor distincte ale aliajului de nichel-titan?","options":[{"id":"A","text":"În faza austenitică, la temperatură joasă, aliajul este ductil și foarte elastic."},{"id":"B","text":"În faza martensitică, aliajul se adaptează mai bine la solicitarea mecanică, dar cu o creștere a tensiunii interne."},{"id":"C","text":"Forma martensitică a aliajului este rezistentă și stabilă."},{"id":"D","text":"Transformarea reversibilă dintre faza austenitică și cea martensitică determină supraelasticitatea aliajului."},{"id":"E","text":"Pentru a prezenta supraelasticitate, instrumentul necesită o cantitate mare de Ni-Ti în faza martensitică."}],"correct":["D","E"],"pages":[127],"source":"set-2"},{"id":"set2-S0pirEVK","fingerprint":"be21b5ddc8acf27a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce aliaj de nichel-titan, introdus în 2010, este obținut printr-un proces termic special și prezintă memorie controlată (CM)?","options":[{"id":"A","text":"Aliajul Twisted File"},{"id":"B","text":"Aliajul CM-wire"},{"id":"C","text":"Sistemul obținut prin tăiere"},{"id":"D","text":"Aliajul R-Phase"},{"id":"E","text":"Aliajul M-Wire"}],"correct":["B"],"pages":[127],"source":"set-2"},{"id":"set2-7kajdEKn","fingerprint":"6341f74f92d3bcb9","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următorii factori influențează riscul de fractură al instrumentelor de nichel-titan prin oboseală ciclică?","options":[{"id":"A","text":"Viteza de rotație a instrumentului."},{"id":"B","text":"Suprafața de contact dintre lamelele tăietoare și pereții canalului."},{"id":"C","text":"Gradul de curbură al canalului radicular."},{"id":"D","text":"Raza de curbură a canalului."},{"id":"E","text":"Presiunea exercitată asupra instrumentului în timpul utilizării."}],"correct":["A","C","D"],"pages":[127],"source":"set-2"},{"id":"set2-4lZORGT9","fingerprint":"ee6075c0743e82b8","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce fenomen este descris ca fiind acumularea stresului în masa aliajului datorită utilizării prelungite într-un canal curb și depinde de numărul de rotații pe care un instrument le poate realiza împotriva unor forțe opuse?","options":[{"id":"A","text":"Memoria controlată"},{"id":"B","text":"Supraelasticitatea"},{"id":"C","text":"Solicitarea prin torsiune"},{"id":"D","text":"Ductilitatea"},{"id":"E","text":"Oboseala ciclică"}],"correct":["E"],"pages":[127],"source":"set-2"},{"id":"set2-iISd65Hq","fingerprint":"ac67dc8f00e75589","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este principala diferență morfologică între partea activă a unui spreader și cea a unui plugger?","options":[{"id":"A","text":"Partea activă a spreaderului este cilindrică, cu vârful plat, în timp ce cea a pluggerului este conică și efilată."},{"id":"B","text":"Nu există nicio diferență morfologică, singura deosebire fiind materialul din care sunt confecționate."},{"id":"C","text":"Ambele instrumente au o parte activă conică, dar pluggerul are un mâner mai lung."},{"id":"D","text":"Partea activă a spreaderului este conică, efilată și netedă, în timp ce cea a pluggerului este cilindrică, cu vârful plat."},{"id":"E","text":"Spreaderele sunt întotdeauna instrumente de tip 'finger', iar pluggerele sunt întotdeauna de tip 'hand'."}],"correct":["D"],"pages":[127],"source":"set-2"},{"id":"set2-1AC526LL","fingerprint":"fe666581a8cf5e92","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect finger spreaderele?","options":[{"id":"A","text":"Permit o îndepărtare ușoară din canal, fără a risca dislocarea gutapercii."},{"id":"B","text":"Prezintă un mâner lung, similar cu cel al unei sonde dentare."},{"id":"C","text":"Conferă o mai mare sensibilitate tactilă comparativ cu hand spreaderele."},{"id":"D","text":"Sunt fabricate exclusiv din oțel inoxidabil."},{"id":"E","text":"Sunt utilizate pentru condensarea verticală la cald a gutapercii."}],"correct":["A","C"],"pages":[127],"source":"set-2"},{"id":"set2-YioG2zBH","fingerprint":"531bea6aeca4ba2d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce consecință are acumularea oboselii ciclice în masa aliajului unui instrument endodontic?","options":[{"id":"A","text":"Scăderea rezistenței acestuia la solicitarea prin torsiune."},{"id":"B","text":"Creșterea diametrului instrumentului la vârf."},{"id":"C","text":"Îmbunătățirea flexibilității instrumentului."},{"id":"D","text":"Creșterea rezistenței acestuia la solicitarea prin torsiune."},{"id":"E","text":"Trecerea aliajului din faza martensitică în cea austenitică."}],"correct":["A"],"pages":[127],"source":"set-2"},{"id":"set2-0GfJmqfM","fingerprint":"92ddd6e03a3245a9","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care este corespondența corectă între culoarea inelului de pe mânerul acului Lentullo și diametrul părții active?","options":[{"id":"A","text":"Un inel verde indică un diametru fin."},{"id":"B","text":"Un inel albastru indică un diametru fin."},{"id":"C","text":"Un inel negru indică un diametru mediu."},{"id":"D","text":"Un inel roșu indică un diametru extrafin."},{"id":"E","text":"Un inel albastru indică un diametru gros."}],"correct":["B","D"],"pages":[128],"source":"set-2"},{"id":"set2-tWgr5d3W","fingerprint":"894e8f78d3314f29","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu obiectivele realizării unei cavități de acces endodontic corecte?","options":[{"id":"A","text":"Crearea unei cavități cu pereți convergenți spre ocluzal pentru retenția materialului provizoriu."},{"id":"B","text":"Vizualizarea directă și identificarea tuturor orificiilor canalelor radiculare."},{"id":"C","text":"Crearea unei cavități cu pereți ușor divergenți spre ocluzal."},{"id":"D","text":"Asigurarea unui acces rectiliniu al instrumentelor până la apex sau până la prima curbură a canalului."},{"id":"E","text":"Eliminarea parțială a plafonului camerei pulpare pentru a conserva țesuturile dure."}],"correct":["B","C","D"],"pages":[128],"source":"set-2"},{"id":"set2-nuyTsIrK","fingerprint":"9bf179b3ee2b3cfb","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce informații esențiale oferă analiza radiologică efectuată anterior realizării cavității de acces?","options":[{"id":"A","text":"Axul longitudinal al rădăcinii care va ghida utilizarea instrumentelor de preparare."},{"id":"B","text":"Numărul de rădăcini, canale radiculare, curburile acestora și lungimea lor aproximativă."},{"id":"C","text":"Identificarea existenței unor rădăcini suplimentare, fiind însă neconcludentă pentru curburi."},{"id":"D","text":"Conturul coroanei la nivelul coletului și localizarea furcației."},{"id":"E","text":"Volumul și poziția camerei pulpare, precum și prezența unor obstacole coronare."}],"correct":["B","E"],"pages":[128],"source":"set-2"},{"id":"set2-Xicjp6aP","fingerprint":"cb2d907b832c0af3","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În timpul preparării cavității de acces la dinții frontali, care este principalul motiv pentru modificarea orientării frezei, astfel încât aceasta să devină paralelă cu axul longitudinal al dintelui, după perforarea inițială?","options":[{"id":"A","text":"Pentru a asigura o mai bună vizibilitate a triunghiului dentinar incizal."},{"id":"B","text":"Pentru a îndepărta complet conținutul camerei pulpare cu o singură mișcare."},{"id":"C","text":"Pentru a lărgi punctul inițial de frezaj la nivelul cingulumului."},{"id":"D","text":"Pentru a trepana plafonul camerei pulpare și a evita riscul de perforație la nivelul pereților laterali sau vestibular."},{"id":"E","text":"Pentru a facilita tranziția de la o freză de turbină la o freză pentru piesa contraunghi."}],"correct":["D"],"pages":[128],"source":"set-2"},{"id":"set2-cfOiNko7","fingerprint":"68b03af9a66e33ad","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Cum se utilizează corect acul Lentullo pentru introducerea pastelor în canalul radicular?","options":[{"id":"A","text":"Prin rotație în sens orar, la viteză convențională, dar cu introducerea sa progresivă spre apex."},{"id":"B","text":"Prin rotație în sens antiorar, la viteză mare, cu o introducere rapidă în canal."},{"id":"C","text":"Static, la viteză convențională, menținându-l pe loc timp de câteva secunde pentru a permite pastei să curgă."},{"id":"D","text":"Prin mișcări de du-te-vino, fără rotație, pentru a compacta pasta la nivel apical."},{"id":"E","text":"Prin rotație în sens orar, la viteză convențională, simultan cu retragerea sa progresivă din canal."}],"correct":["E"],"pages":[128],"source":"set-2"},{"id":"set2-C5wb8XBS","fingerprint":"9a771f0be3398468","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt etapele și procedurile corecte în realizarea cavității de acces endodontic, de la planificare la finalizare?","options":[{"id":"A","text":"Realizarea unui sondaj parodontal pentru a localiza joncțiunea smalț-cement."},{"id":"B","text":"Îndepărtarea tavanului camerei pulpare la dinții frontali cu o freză sferică la turbină, cu mișcări din exterior spre interior."},{"id":"C","text":"Analiza radiologică pentru a determina numărul și curburile canalelor radiculare."},{"id":"D","text":"Trepanarea smalțului și a dentinei, urmată de îndepărtarea completă a plafonului camerei pulpare."},{"id":"E","text":"Modificarea orientării frezei la dinții frontali pentru a deveni perpendiculară pe axul dintelui după perforarea tavanului."}],"correct":["A","C"],"pages":[128],"source":"set-2"},{"id":"set2-vq9R7tJV","fingerprint":"1b9257d09746402d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este punctul inițial de frezaj pentru realizarea cavității de acces la dinții frontali?","options":[{"id":"A","text":"La nivelul marginii incizale, pentru a asigura un acces rectiliniu."},{"id":"B","text":"Pe fața orală, la nivelul cingulumului, în treimea mezială a dintelui."},{"id":"C","text":"Pe fața vestibulară, în centrul dintelui, pentru un acces mai direct."},{"id":"D","text":"Pe fața orală, ușor incizal față de cingulum, la intersecția treimii medii mezio-distale cu cea medie cervico-incizală."},{"id":"E","text":"Pe fața orală, în șanțul de la nivelul cingulumului."}],"correct":["D"],"pages":[128],"source":"set-2"},{"id":"set2-9CFt1v7g","fingerprint":"4f5a3eb7476ef72b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt etapele și orientările corecte ale frezei în timpul preparării cavității de acces la un dinte frontal cu camera pulpară neretrasă?","options":[{"id":"A","text":"Tavanul camerei pulpare se îndepărtează cu freze Endo-Z prin mișcări de translație."},{"id":"B","text":"După pătrunderea 1-2 mm în dentină, orientarea frezei devine paralelă cu axul longitudinal al dintelui."},{"id":"C","text":"Freza se orientează de la început paralel cu axul longitudinal al dintelui pentru a evita perforațiile."},{"id":"D","text":"Orientarea inițială a frezei este perpendiculară pe fața orală, până la perforarea tavanului camerei pulpare."},{"id":"E","text":"Punctul de frezaj inițial se alege în centrul feței orale, în cingulum."}],"correct":["B","D"],"pages":[129],"source":"set-2"},{"id":"set2-Q_dPuye6","fingerprint":"2b48be7f835a7a05","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce scop are eliminarea celor două triunghiuri dentinare (incizal și cervical) după îndepărtarea tavanului camerei pulpare la dinții frontali?","options":[{"id":"A","text":"Asigură o mai bună vizibilitate a planșeului camerei pulpare."},{"id":"B","text":"Facilitează identificarea orificiilor de emergență a canalelor suplimentare."},{"id":"C","text":"Permite accesul rectiliniu al instrumentelor în canalul radicular."},{"id":"D","text":"Reduce riscul de perforație la nivelul peretelui vestibular."},{"id":"E","text":"Previne fractura instrumentelor endodontice la nivelul coroanei."}],"correct":["C"],"pages":[129],"source":"set-2"},{"id":"set2-SJLA0w7k","fingerprint":"0d957ee4fc73ad44","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristicile cavității de acces la dinții frontali maxilari?","options":[{"id":"A","text":"La toți dinții frontali maxilari, cavitatea se localizează în cingulum."},{"id":"B","text":"La incisivii centrali, cavitatea are o formă triunghiulară rotunjită, cu pereții divergenți spre palatinal."},{"id":"C","text":"Pereții cavității de acces la incisivii centrali sunt convergenți spre palatinal."},{"id":"D","text":"La canini, cavitatea de acces este triunghiulară, similară cu cea de la incisivii centrali."},{"id":"E","text":"La incisivii laterali, cavitatea este ovoidală și poate necesita o extensie incizală pentru accesul în linie dreaptă."}],"correct":["B","E"],"pages":[129],"source":"set-2"},{"id":"set2-WqtvGpE4","fingerprint":"1c8a10004f249462","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce particularități prezintă realizarea cavității de acces la dinții frontali mandibulari?","options":[{"id":"A","text":"Acești dinți prezintă întotdeauna un singur canal radicular, simplificând accesul."},{"id":"B","text":"Punctul inițial de frezaj este situat strict pe marginea incizală din cauza uzurii frecvente."},{"id":"C","text":"Extensia incizală este adesea necesară pentru a accesa ambele canale radiculare, dacă există."},{"id":"D","text":"Pereții cavității sunt divergenți spre incizal."},{"id":"E","text":"Cavitatea are întotdeauna o formă ovoidală, cu axul lung mezio-distal."}],"correct":["C","D"],"pages":[129],"source":"set-2"},{"id":"set2-AHArPh5k","fingerprint":"2e710cd7b9826729","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este localizarea punctului inițial de frezaj pentru prepararea cavității de acces la premolarii maxilari?","options":[{"id":"A","text":"Deasupra orificiului de emergență al canalului palatinal."},{"id":"B","text":"Pe panta cuspidului vestibular."},{"id":"C","text":"În centrul șanțului mezio-distal."},{"id":"D","text":"În foseta distală a feței ocluzale."},{"id":"E","text":"Ușor vestibularizat față de centrul feței ocluzale."}],"correct":["C"],"pages":[129],"source":"set-2"},{"id":"set2-Aqqkb9fq","fingerprint":"175d4d6dbbe9d300","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce instrumente sunt utilizate pentru a îndepărta tavanul camerei pulpare și pentru a verifica îndepărtarea completă a acestuia la premolari?","options":[{"id":"A","text":"Freze Gates-Glidden pentru îndepărtare și ace Kerr pentru verificare."},{"id":"B","text":"O freză sferică de turbină pentru îndepărtare și sonda 17 pentru verificare."},{"id":"C","text":"O freză sferică cu gât lung pentru îndepărtare și sonda 16 pentru verificare."},{"id":"D","text":"O freză cu vârful inactiv (tip Endo-Z) pentru îndepărtare și sonda 17 pentru verificare."},{"id":"E","text":"O freză cu vârf inactiv (tip Endo-Z) pentru îndepărtare și sonda 16 pentru verificare."}],"correct":["D"],"pages":[129],"source":"set-2"},{"id":"set2-MzRRgO2z","fingerprint":"b9ed4ff79f10bb4f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este forma cavității de acces la premolarii maxilari și de ce are această formă?","options":[{"id":"A","text":"Ovalară cu axul lung vestibulo-palatinal, datorită formei camerei pulpare și aplatizării mezio-distale a rădăcinii."},{"id":"B","text":"Triunghiulară, datorită celor trei coarne pulpare."},{"id":"C","text":"Ovalară cu axul lung mezio-distal, pentru a uni cei doi cuspizi."},{"id":"D","text":"Circulară, pentru a conserva cât mai multă structură dentară."},{"id":"E","text":"Ovalară, ușor vestibularizată, din cauza angulației coroană-rădăcină."}],"correct":["A"],"pages":[129],"source":"set-2"},{"id":"set2-NjuzhLgB","fingerprint":"33bc23358dd44b20","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce particularități anatomice influențează forma și localizarea cavității de acces la primul premolar mandibular?","options":[{"id":"A","text":"Rădăcina este aplatizată mezio-distal, ceea ce impune o cavitate îngustă vestibulo-lingual."},{"id":"B","text":"Cuspizii asimetrici, cel lingual fiind mai voluminos, determină localizarea camerei pulpare sub acesta."},{"id":"C","text":"Cavitatea este ușor vestibularizată din cauza unghiului deschis lingual dintre axul coronar și cel radicular."},{"id":"D","text":"Camera pulpară este localizată aproape în întregime sub cuspidul vestibular datorită asimetriei cuspizilor."},{"id":"E","text":"Pereții laterali ai cavității sunt convergenți spre ocluzal pentru a conserva structura dentară."}],"correct":["C","D"],"pages":[129],"source":"set-2"},{"id":"set2-l7lUcce2","fingerprint":"34412191feb34fe0","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce se poate afirma despre o cameră pulpară complet calcificată în timpul realizării accesului endodontic?","options":[{"id":"A","text":"Se recomandă utilizarea unei radiografii preoperatorii pentru a determina distanța până la tavanul camerei pulpare."},{"id":"B","text":"Senzația de \"cădere în gol\" la deschiderea acesteia este absentă."},{"id":"C","text":"Triunghiurile dentinare cervical și incizal nu mai sunt prezente."},{"id":"D","text":"Trepanarea plafonului se realizează exclusiv cu freze Endo-Z."},{"id":"E","text":"Riscul de perforație este diminuat datorită grosimii crescute a pereților dentinari."}],"correct":["B"],"pages":[129],"source":"set-2"},{"id":"set2-v_8VBiwY","fingerprint":"c44c3998f666292a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este punctul inițial de frezaj pentru realizarea accesului endodontic la molari?","options":[{"id":"A","text":"În șanțul intercuspidian mezio-distal."},{"id":"B","text":"La nivelul crestei oblice a molarilor maxilari."},{"id":"C","text":"Într-una din gropițele secundare ale feței ocluzale."},{"id":"D","text":"Pe panta cuspidului mezio-vestibular."},{"id":"E","text":"În foseta centrală, perpendicular pe fața ocluzală."}],"correct":["E"],"pages":[130],"source":"set-2"},{"id":"set2-28RDxWWK","fingerprint":"79c8c13a6f65bee8","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce instrument este recomandat pentru îndepărtarea completă a tavanului camerei pulpare, cu scopul de a evita perforarea planșeului în cazul cavității de acces a molarilor?","options":[{"id":"A","text":"Anse ultrasonice."},{"id":"B","text":"O freză cilindro-conică, cu vârf inactiv de tip EndoZ."},{"id":"C","text":"O freză sferică diamantată la viteză înaltă."},{"id":"D","text":"O freză Endo Acces."},{"id":"E","text":"O sondă 17."}],"correct":["B"],"pages":[130],"source":"set-2"},{"id":"set2-F2Pziif1","fingerprint":"5028b48e2578fb2a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile cavității de acces pentru molarii maxilari?","options":[{"id":"A","text":"La molarul II maxilar, orificiul canalului disto-vestibular este situat mai spre vestibular față de linia ce unește canalul mezio-vestibular cu cel palatinal."},{"id":"B","text":"Localizarea canalelor radiculare începe de obicei cu cel palatinal, care este mai larg și mai drept."},{"id":"C","text":"Pereții axiali ai cavității de acces sunt convergenți spre ocluzal."},{"id":"D","text":"La primul molar maxilar, latura mezială a cavității de acces este cea mai lungă, iar cea palatinală cea mai scurtă."},{"id":"E","text":"În prezența unui al doilea canal mezio-vestibular, cavitatea de acces tinde să aibă o formă de romb."}],"correct":["B","D","E"],"pages":[130],"source":"set-2"},{"id":"set2-6TrnyoeZ","fingerprint":"da3083cd520483c0","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce formă caracteristică are cavitatea de acces la molarii mandibulari și unde este localizată pe fața ocluzală?","options":[{"id":"A","text":"O formă triunghiulară, similară molarilor maxilari, localizată mai spre vestibular."},{"id":"B","text":"O formă de trapez cu baza mare situată distal, localizată central pe fața ocluzală."},{"id":"C","text":"O formă de trapez cu baza mare situată mezial, localizată mai înspre partea mezială a feței ocluzale."},{"id":"D","text":"O formă de romb, localizată în jumătatea distală a feței ocluzale."},{"id":"E","text":"O formă patrulateră, similară molarului unu superior, localizată mai spre lingual."}],"correct":["C"],"pages":[130],"source":"set-2"},{"id":"set2--4PSGaGb","fingerprint":"7fb24fdc1896f07d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Cum se modifică conturul ocluzal al cavității de acces la un molar mandibular în situația existenței a două canale distale?","options":[{"id":"A","text":"Baza mare a trapezului se va îngusta."},{"id":"B","text":"Conturul devine triunghiular."},{"id":"C","text":"Laturile laterale ale trapezului devin paralele."},{"id":"D","text":"Baza mică a trapezului se va mări."},{"id":"E","text":"Conturul rămâne neschimbat, canalele fiind localizate cu o singură sondare."}],"correct":["D"],"pages":[130],"source":"set-2"},{"id":"set2-E6VCXjmD","fingerprint":"00840e58793d8e21","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt obiectivele tratamentului chemo-mecanic (mecanico-antiseptic) al canalelor radiculare?","options":[{"id":"A","text":"Obținerea unei forme specifice a canalului radicular care să permită o obturare tridimensională."},{"id":"B","text":"Îndepărtarea microorganismelor din sistemul de canale radiculare."},{"id":"C","text":"Îndepărtarea completă a tavanului camerei pulpare cu o freză EndoZ."},{"id":"D","text":"Finisarea pereților axiali ai cavității de acces cu anse ultrasonice."},{"id":"E","text":"Îndepărtarea din canalul radicular a resturilor organice și anorganice."}],"correct":["A","B","E"],"pages":[130],"source":"set-2"},{"id":"set2-2tMhpDEu","fingerprint":"5faa9d195753b0d2","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce aspect specific trebuie luat în considerare la avansarea frezei spre camera pulpară în cazul molarilor inferiori pentru a evita complicațiile?","options":[{"id":"A","text":"Forma de romb a camerei pulpare."},{"id":"B","text":"Masca de o punte de dentină a celui de-al doilea canal mezio-vestibular."},{"id":"C","text":"Localizarea orificiului canalului palatinal."},{"id":"D","text":"Axul de înclinare al dintelui în sens vestibulo-lingual și mezio-distal."},{"id":"E","text":"Păstrarea paralelismului frezei cu peretele distal al dintelui."}],"correct":["D"],"pages":[130],"source":"set-2"},{"id":"set2-HnmByoRy","fingerprint":"1ddf817fd1ee90cf","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele obținerii unei forme conice continue a canalului radicular preparat?","options":[{"id":"A","text":"Asigură menținerea materialului de obturare în limitele canalului."},{"id":"B","text":"Crește rezistența pereților radiculari la fractură prin menținerea dentinei."},{"id":"C","text":"Facilitează pătrunderea soluțiilor de lavaj endodontic."},{"id":"D","text":"Permite o distribuție favorabilă a forțelor în cursul realizării obturației de canal."},{"id":"E","text":"Permite instrumentelor să ajungă și să instrumenteze mai ușor regiunea apicală."}],"correct":["C","D","E"],"pages":[131],"source":"set-2"},{"id":"set2-Wk0Zijg3","fingerprint":"25281dda21869b17","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este cauza principală a deplasării externe a foramenului apical (transport extern) în timpul instrumentării unui canal curb?","options":[{"id":"A","text":"Menținerea diametrului foramenului apical cât mai redus."},{"id":"B","text":"Acumularea de resturi dentinare în apropierea constricției apicale."},{"id":"C","text":"Utilizarea unor instrumente cu flexibilitate mare, precurbate la vârf."},{"id":"D","text":"Forțarea unui instrument în direcție apicală pe fața internă a curburii."},{"id":"E","text":"Memoria elastică a instrumentelor care tind să revină la forma rectilinie."}],"correct":["E"],"pages":[131],"source":"set-2"},{"id":"set2-_va6ZtbS","fingerprint":"f85faccb9737cdbb","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Conform obiectivelor mecanice ale preparării canalului radicular, ce afirmații sunt adevărate în legătură cu menținerea traseului anatomic original?","options":[{"id":"A","text":"Este important să se mențină cât mai multă dentină radiculară pentru a preveni scăderea rezistenței pereților și riscul de perforații."},{"id":"B","text":"Păstrarea traseului original este realizată prin îndepărtarea unei cantități mai mari de dentină de la nivelul pereților opuși curburii."},{"id":"C","text":"Canalele cu secțiune transversală ovală trebuie transformate într-o formă circulară pentru o obturare optimă."},{"id":"D","text":"Pentru a favoriza accesul în treimea apicală, se îndepărtează o cantitate mai mare de dentină din această regiune."},{"id":"E","text":"Canalul preparat trebuie să se suprapună peste spațiul canalului inițial și să îl includă."}],"correct":["A","B","E"],"pages":[131],"source":"set-2"},{"id":"set2-stIO17-G","fingerprint":"073a5d4771a89479","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce consecință morfologică are transportul extern al foramenului apical?","options":[{"id":"A","text":"Reducerea diametrului foramenului apical sub dimensiunea inițială."},{"id":"B","text":"Crearea unui prag pe peretele intern al curburii apicale."},{"id":"C","text":"Formarea unui foramen apical în formă de lacrimă sau clepsidră."},{"id":"D","text":"Blocarea canalului prin acumularea de resturi dentinare."},{"id":"E","text":"Păstrarea formei originale circulare a foramenului."}],"correct":["C"],"pages":[131],"source":"set-2"},{"id":"set2-_DfSL0vv","fingerprint":"f18c8c5e2f82723a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este principalul obiectiv al menținerii unui diametru cât mai redus pentru foramenul apical?","options":[{"id":"A","text":"Păstrarea rezistenței pereților radiculari la fractură."},{"id":"B","text":"Facilitarea accesului instrumentelor în regiunea apicală."},{"id":"C","text":"Asigurarea menținerii materialului de obturare în limitele canalului."},{"id":"D","text":"Creșterea eficienței soluțiilor de lavaj endodontic."},{"id":"E","text":"Prevenirea deplasării externe a foramenului apical."}],"correct":["C"],"pages":[131],"source":"set-2"},{"id":"set2-Qaz2WDfw","fingerprint":"96298239d9deff1f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele reprezintă incidente ce pot apărea în cursul instrumentării dacă poziția și forma originală a foramenului apical nu sunt menținute corespunzător?","options":[{"id":"A","text":"Deplasarea internă a foramenului apical (transport intern)."},{"id":"B","text":"Crearea unui prag sau producerea unei perforații."},{"id":"C","text":"Obținerea unei forme conice uniforme a canalului radicular."},{"id":"D","text":"Deplasarea externă a foramenului (transport extern)."},{"id":"E","text":"Menținerea traseului anatomic original al canalului."}],"correct":["A","B","D"],"pages":[131],"source":"set-2"},{"id":"set2-mlEiG2sk","fingerprint":"3b92dd3a49218baf","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform unei școli de endodonție, în cazul în care se avansează cu dificultate cu un ac de 0,10 mm la prima pătrundere în canal, ce dimensiune se recomandă pentru instrumentele de lărgire apicală?","options":[{"id":"A","text":"Dimensiunea este irelevantă, contând doar forma conică."},{"id":"B","text":"O dimensiune mai mare de 0,20 mm."},{"id":"C","text":"0,10 mm, menținându-se diametrul inițial."},{"id":"D","text":"0,20 mm."},{"id":"E","text":"Dimensiunea maximă pe care o permite curbura canalului."}],"correct":["D"],"pages":[131],"source":"set-2"},{"id":"set2-PHvUDVCw","fingerprint":"701f11240b4e8a4a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele reprezintă abordări distincte în ceea ce privește lărgirea foramenului apical în endodonție?","options":[{"id":"A","text":"Utilizarea instrumentelor de 0,20 mm dacă un ac de 0,10 mm avansează cu dificultate, menținând diametrul inițial dacă este mai mare de 0,20 mm."},{"id":"B","text":"Menținerea diametrului foramenului apical cât mai redus posibil, fără excepție, pentru a preveni extruzia materialului de obturare."},{"id":"C","text":"Lărgirea canalului la nivel apical cu trei numere peste instrumentul care a determinat diametrul inițial, și chiar mai mult în cazul dinților infectați."},{"id":"D","text":"Lărgirea sistematică a foramenului la o dimensiune standard de 0,25 mm pentru toți dinții, indiferent de diametrul inițial."},{"id":"E","text":"Evitarea îndepărtării unei cantități mari de dentină apicală dacă se asigură o conicitate adecvată a canalului pentru o irigare corectă."}],"correct":["A","C","E"],"pages":[132],"source":"set-2"},{"id":"set2-bpY4DaSg","fingerprint":"513640870b09824a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform obiectivelor biologice ale instrumentării canalului radicular, ce instrument este singurul care poate trece dincolo de foramenul apical?","options":[{"id":"A","text":"Acul de irigare activat ultrasonic."},{"id":"B","text":"Un ac de 0,10 mm în toate cazurile."},{"id":"C","text":"Acul care asigură permeabilitatea apicală (“apical patency”)."},{"id":"D","text":"Orice instrument rotativ din nichel-titan."},{"id":"E","text":"Primul instrument care a determinat diametrul inițial al canalului."}],"correct":["C"],"pages":[132],"source":"set-2"},{"id":"set2-o34WtIg5","fingerprint":"8ae6904189e5a44e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce element este considerat indispensabil, alături de instrumentare, pentru eliminarea completă a conținutului canalului radicular și dezinfecția avansată a acestuia?","options":[{"id":"A","text":"O conicitate adecvată a canalului radicular."},{"id":"B","text":"Utilizarea exclusivă a tehnicilor manuale din oțel inoxidabil."},{"id":"C","text":"Irigarea endodontică activată ultrasonic, sonic sau laser."},{"id":"D","text":"Lărgirea foramenului apical cu cel puțin trei numere superioare."},{"id":"E","text":"Aplicarea tehnicii forțelor compensate (balanced force technique)."}],"correct":["C"],"pages":[132],"source":"set-2"},{"id":"set2-FPz2h59S","fingerprint":"790849148649ee4e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele lărgirii preliminare a canalului radicular (preevazarea coronară)?","options":[{"id":"A","text":"Permite pătrunderea mai rapidă a acului de irigare în zonele profunde ale canalului."},{"id":"B","text":"Asigură un acces sigur și controlat la nivelul treimii apicale, cu o sensibilitate tactilă superioară."},{"id":"C","text":"Elimină necesitatea utilizării instrumentelor rotative din nichel-titan."},{"id":"D","text":"Permite o precurbare a instrumentului, care poate fi menținută până la atingerea treimii apicale."},{"id":"E","text":"Reduce cantitatea de resturi dentinare și floră microbiană împinse periapical."}],"correct":["A","B","D","E"],"pages":[132],"source":"set-2"},{"id":"set2-42iWOXLg","fingerprint":"3a2d59e2fc3a84b3","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Pentru o mai bună înțelegere a instrumentării, în câte regiuni sau treimi este împărțită lungimea canalului radicular și care este lungimea aproximativă a fiecărei treimi?","options":[{"id":"A","text":"Cinci regiuni, corespunzătoare numărului de instrumente utilizate."},{"id":"B","text":"Trei treimi (coronară, medie și apicală), fiecare având o lungime fixă de 4 mm."},{"id":"C","text":"Trei treimi (coronară, medie și apicală), fiecare având o lungime cuprinsă între 3 și 5 mm."},{"id":"D","text":"Patru regiuni (coronară, medie, apicală și foraminală), cu lungimi variabile."},{"id":"E","text":"Două treimi (coronară și apicală), fiecare având o lungime de 6-8 mm."}],"correct":["C"],"pages":[132],"source":"set-2"},{"id":"set2-PtdtWJhj","fingerprint":"3947b4c26d7201c5","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este un avantaj principal al preparării treimilor coronară și medie ale canalului radicular înainte de instrumentarea treimii apicale?","options":[{"id":"A","text":"Permite determinarea lungimii de lucru reale fără a utiliza un apex locator."},{"id":"B","text":"Asigură o curbură mai accentuată în treimea coronară pentru o mai bună retenție a materialului de obturație."},{"id":"C","text":"Se reduce cantitatea de resturi dentinare și floră microbiană împinse periapical."},{"id":"D","text":"Scade timpul total de lucru prin omiterea irigării endodontice."},{"id":"E","text":"Elimină complet necesitatea utilizării acelor Kerr manuale în tratamentul endodontic."}],"correct":["C"],"pages":[133],"source":"set-2"},{"id":"set2-7WSUq9tv","fingerprint":"d14912ec2faaf2cb","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce instrument este recomandat pentru explorarea inițială a configurației unui canal radicular?","options":[{"id":"A","text":"Un instrument PathFile precurbat."},{"id":"B","text":"Un instrument rotativ de nichel titan cu conicitate mare."},{"id":"C","text":"Un ac Kerr de dimensiuni reduse, 8 sau 10."},{"id":"D","text":"O freză Gates Glidden de diametru mic."},{"id":"E","text":"Un ac Kerr de dimensiune 25 pentru a asigura o permeabilitate adecvată."}],"correct":["C"],"pages":[133],"source":"set-2"},{"id":"set2-JK2zd5jB","fingerprint":"55a59f028ec00169","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Un medic dentist utilizează un ac Kerr pentru a explora un canal radicular, dar instrumentul nu poate înainta până la lungimea de lucru estimată. Care este mișcarea recomandată pentru a încerca să progreseze în canal?","options":[{"id":"A","text":"O mișcare de rotație reciprocă alternativă, orară și antiorară (\"watch winding\")."},{"id":"B","text":"Mobilizarea acului în direcție apico-coronară, în mișcări ample de 3-4 mm."},{"id":"C","text":"Aplicarea unui gel pe bază de hipoclorit de sodiu pentru a dizolva obstacolul."},{"id":"D","text":"Retragerea completă a acului și utilizarea unei freze Gates Glidden."},{"id":"E","text":"Forțarea acului în direcție apicală cu presiune constantă."}],"correct":["A"],"pages":[133],"source":"set-2"},{"id":"set2-WpEtTGBk","fingerprint":"0613264c3b9f469e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre următoarele afirmații descriu corect mișcarea de rotație alternativă (\"watch winding\")?","options":[{"id":"A","text":"Constă în rotirea acului în sens orar între 30-60 de grade și apoi în sens antiorar în același interval."},{"id":"B","text":"Prezintă un risc ridicat de a produce praguri în pereții canalului radicular."},{"id":"C","text":"Este o mișcare agresivă, care implică împingerea cu forță a instrumentului în canal."},{"id":"D","text":"Rotația în sens orar are rolul de a tăia și îndepărta dentina parietală."},{"id":"E","text":"Rotația în sens antiorar propulsează vârful și lamelele tăietoare mai adânc în canal."}],"correct":["A"],"pages":[133],"source":"set-2"},{"id":"set2-IyDMF3zq","fingerprint":"e479fe729ab7324b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt posibilele cauze pentru care un ac Kerr nu reușește să înainteze în canal, chiar și după aplicarea mișcării \"watch winding\"?","options":[{"id":"A","text":"O curbură apicală abruptă."},{"id":"B","text":"O lărgire coronară excesivă realizată în prealabil."},{"id":"C","text":"Utilizarea unui gel lubrifiant pe bază de EDTA."},{"id":"D","text":"Prezența unui rezervor de soluție de lavaj în camera pulpară."},{"id":"E","text":"O curbură situată în treimea coronară, care împiedică acul să urmeze traiectoria canalului."}],"correct":["A","E"],"pages":[133],"source":"set-2"},{"id":"set2-9FSyFFlN","fingerprint":"fa0d1c51d68d1d39","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce instrumente pot fi utilizate pentru realizarea lărgirii treimii coronare a canalului radicular (preevazare coronară)?","options":[{"id":"A","text":"Exclusiv ace Kerr pilă de la 8 la 25."},{"id":"B","text":"Apex locator."},{"id":"C","text":"Freze Gates Glidden."},{"id":"D","text":"Instrumente de nichel titan de conicitate mare în mișcare de rotație."},{"id":"E","text":"Instrumente PathFile sau One G."}],"correct":["C","D"],"pages":[133],"source":"set-2"},{"id":"set2-8LaaEH5h","fingerprint":"185fe0e0493280e0","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile etapei de preevazare coronară a canalului radicular?","options":[{"id":"A","text":"În cazul canalelor meziale ale molarilor maxilari, se acționează pe peretele distal."},{"id":"B","text":"Scopul principal este de a reduce curbura treimii coronare și de a lărgi canalul."},{"id":"C","text":"Instrumentele trebuie să acționeze uniform pe toți pereții radiculari pentru a menține central canalul."},{"id":"D","text":"Această etapă elimină necesitatea irigării și verificării permeabilității canalului."},{"id":"E","text":"Este indicat ca instrumentele să acționeze preponderent pe peretele radicular opus curburii rădăcinii."}],"correct":["B","E"],"pages":[133],"source":"set-2"},{"id":"set2-1XMvPvv-","fingerprint":"2b6d80e8b09869fa","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele utilizării instrumentelor rotative de nichel-titan, cum ar fi ProTaper SX sau One Flare, în comparație cu frezele Gates Glidden?","options":[{"id":"A","text":"Curăță și relocalizează intrarea în canalul radicular."},{"id":"B","text":"Necesită aplicarea unei presiuni apicale pentru a preveni formarea de praguri."},{"id":"C","text":"Sunt mai lungi și au o conicitate redusă, permițând o pătrundere mai profundă."},{"id":"D","text":"Elimină interferențele dentinare de la intrarea în canalele radiculare."},{"id":"E","text":"Instrumentează și conicizează treimea coronară a canalului radicular."}],"correct":["A","D","E"],"pages":[134],"source":"set-2"},{"id":"set2-pXqm8aXi","fingerprint":"334ee337421821cc","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce reprezintă realizarea permeabilizării canalului radicular (cateterizarea)?","options":[{"id":"A","text":"Utilizarea exclusivă a acelor de calibru mare pentru a sonda canalul radicular."},{"id":"B","text":"Negocierea întregului canal până la foramenul apical și depășirea acestuia cu 0,5-1 mm."},{"id":"C","text":"Lărgirea treimii coronare și mediene a canalului pentru a facilita accesul."},{"id":"D","text":"Stabilirea lungimii de lucru a canalului prin măsurarea distanței până la constricția apicală."},{"id":"E","text":"Confirmarea radiologică a poziției acului exact la nivelul constricției apicale."}],"correct":["B"],"pages":[134],"source":"set-2"},{"id":"set2-PTf1SgsR","fingerprint":"6e910a58349de885","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect tehnica de realizare a permeabilității canalului radicular?","options":[{"id":"A","text":"În cazul unei curburi apicale importante, acul trebuie menținut drept și avansat cu presiune."},{"id":"B","text":"După permeabilizarea foramenului, se execută mișcări axiale de mică amplitudine (0,5-2 mm) pentru a lărgi zona apicală."},{"id":"C","text":"Dacă acul nu avansează pasiv, se pot efectua mișcări de rotație reciprocă (watch winding)."},{"id":"D","text":"Permeabilizarea se realizează întotdeauna înainte de stabilirea unei lungimi estimative pe radiografie."},{"id":"E","text":"Se utilizează ace fine, de dimensiuni 6, 8, sau 10, care sunt conduse pasiv în canal."}],"correct":["B","C","E"],"pages":[134],"source":"set-2"},{"id":"set2-PCvq9mWc","fingerprint":"c670f1d420c1c1e9","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Cum se calculează lungimea estimativă a canalului radicular pe o radiografie preoperatorie?","options":[{"id":"A","text":"Măsurând distanța dintre joncțiunea cemento-dentinară și un reper coronar."},{"id":"B","text":"Măsurând distanța dintre apexul radiologic și un reper coronar, apoi adăugând 0,5-1 mm."},{"id":"C","text":"Utilizând un apex locator înainte de orice măsurătoare radiografică."},{"id":"D","text":"Măsurând distanța dintre apexul radiologic și un reper coronar, apoi scăzând 1 mm."},{"id":"E","text":"Măsurând distanța exactă dintre apexul radiologic și un reper coronar, fără nicio ajustare."}],"correct":["D"],"pages":[134],"source":"set-2"},{"id":"set2-hRaR8193","fingerprint":"d68c9b61389f57a1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce reprezintă constricția apicală din punct de vedere endodontic?","options":[{"id":"A","text":"Zona apicală cea mai îngustă a canalului radicular, care reprezintă limita de instrumentare și obturare."},{"id":"B","text":"O zonă în care contactul dintre materialul de obturație și pereții canalului se realizează pe cea mai mare suprafață."},{"id":"C","text":"O zonă situată întotdeauna la exact 1 mm de apexul anatomic al dintelui."},{"id":"D","text":"Punctul final al canalului, care trebuie depășit cu 0,5-1 mm pentru a asigura permeabilitatea."},{"id":"E","text":"O limită histologică cu o poziție variabilă, numită și joncțiune cemento-dentinară."}],"correct":["A"],"pages":[134],"source":"set-2"},{"id":"set2-bi2qh09z","fingerprint":"4de2c5ef639f24f2","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații privind localizarea constricției apicale sunt corecte?","options":[{"id":"A","text":"Poziția sa este constantă și nu variază de la un dinte la altul."},{"id":"B","text":"Distanța medie față de apexul anatomic este de 0,98 mm la premolarii superiori."},{"id":"C","text":"Distanța medie față de apexul anatomic este de 0,98 mm la incisivii inferiori."},{"id":"D","text":"Este situată la o distanță fixă de 1 mm de apex la toți dinții."},{"id":"E","text":"Distanța medie față de apexul anatomic este de 0,79 mm la incisivii inferiori."}],"correct":["B","E"],"pages":[134],"source":"set-2"},{"id":"set2-BJWdH4Iw","fingerprint":"aa0ab8dd92a3325a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este tehnica corectă de utilizare a frezelor Gates Glidden conform recomandărilor?","options":[{"id":"A","text":"Se introduc pasiv până la constricția apicală, fără mișcări de rotație."},{"id":"B","text":"Se aplică presiune apicală constantă pentru a depăși curbura canalului."},{"id":"C","text":"Se utilizează în ordine descrescătoare, de la 6 la 1, în toată lungimea canalului."},{"id":"D","text":"Se folosesc în ordine crescătoare, doar în porțiunea rectilinie a canalului, cu o mișcare de retragere și înclinare."},{"id":"E","text":"Se utilizează printr-o mișcare de apăsare (pensulare) pe peretele intern al curburii."}],"correct":["D"],"pages":[134],"source":"set-2"},{"id":"set2-h4zzI1GT","fingerprint":"7280c2173bc34262","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce definește constricția apicală în anatomia canalului radicular?","options":[{"id":"A","text":"Imaginea radiologică a punctului terminus al rădăcinii."},{"id":"B","text":"Vârful morfologic, fizic, al rădăcinii dintelui."},{"id":"C","text":"Zona apicală cea mai îngustă a canalului, reprezentând limita pentru instrumentare și obturare."},{"id":"D","text":"Deschiderea canalului radicular pe suprafața externă a rădăcinii."},{"id":"E","text":"Punctul în care pereții canalului sunt paraleli pe o distanță de peste 3 mm."}],"correct":["C"],"pages":[135],"source":"set-2"},{"id":"set2-4nsCPvnH","fingerprint":"42e25210c1325756","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele tipuri de constricții apicale sunt recunoscute?","options":[{"id":"A","text":"Paralelă, cu pereții canalului paraleli pe o distanță de până la 3 mm."},{"id":"B","text":"Divergentă, cu lărgire spre apexul anatomic."},{"id":"C","text":"Multiple constricții situate apical."},{"id":"D","text":"Aspect convențional, în formă de trunchi de con."},{"id":"E","text":"În formă de clepsidră, cu două zone îngustate."}],"correct":["A","C","D"],"pages":[135],"source":"set-2"},{"id":"set2-SAH0xtQX","fingerprint":"ad89314285517f3e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Referitor la reperele anatomice apicale, care dintre următoarele afirmații despre distanțe sunt corecte?","options":[{"id":"A","text":"Distanța dintre constricția apicală și apexul anatomic al dintelui este, în medie, de aproximativ 1 mm."},{"id":"B","text":"Distanța dintre foramenul apical și constricția apicală este mai mare la pacienții tineri comparativ cu cei vârstnici."},{"id":"C","text":"Distanța dintre foramenul apical și constricția apicală variază între 0,2 mm și 0,6 mm."},{"id":"D","text":"Foramenul apical poate fi situat la o distanță de 0 până la 2 mm coronar de apexul anatomic."},{"id":"E","text":"Constricția apicală se află întotdeauna la exact 1 mm de foramenul apical."}],"correct":["A","C","D"],"pages":[135],"source":"set-2"},{"id":"set2-ucgOCHua","fingerprint":"4c88c2b56db3e50c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce semnificație are afișarea valorii '0' pe display-ul unui apex locator în timpul determinării lungimii de lucru?","options":[{"id":"A","text":"Există o eroare de măsurare din cauza contactului cu o restaurare metalică."},{"id":"B","text":"Canalul radicular este complet uscat, permițând o citire precisă."},{"id":"C","text":"S-a atins lungimea de lucru finală și se poate începe obturarea."},{"id":"D","text":"Acul se află exact la nivelul constricției apicale."},{"id":"E","text":"Vârful acului a atins ligamentul periodontal."}],"correct":["E"],"pages":[135],"source":"set-2"},{"id":"set2-4C1tx7pH","fingerprint":"05a154c364082ef1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce ajustare se aplică lungimii măsurate cu un apex locator (când acesta indică atingerea ligamentului periodontal) pentru a obține lungimea de lucru (LL)?","options":[{"id":"A","text":"Se scade o valoare variabilă, între 0,2 și 0,6 mm."},{"id":"B","text":"Se scad 0,5 mm."},{"id":"C","text":"Se adaugă 0,5 mm."},{"id":"D","text":"Lungimea se utilizează fără nicio ajustare."},{"id":"E","text":"Se scade 1 mm."}],"correct":["B"],"pages":[135],"source":"set-2"},{"id":"set2-QKj8Aleb","fingerprint":"075bc84eb9ad427c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele reprezintă condiții esențiale pentru utilizarea corectă a apex locatoarelor?","options":[{"id":"A","text":"Electrodul labial trebuie aplicat la nivelul comisurii buzei superioare."},{"id":"B","text":"Progresia mișcării afișate pe ecranul aparatului trebuie să corespundă perfect cu cea din canal."},{"id":"C","text":"Diametrul acului Kerr utilizat trebuie să fie adecvat diametrului canalului radicular."},{"id":"D","text":"Dintele trebuie să fie izolat, de exemplu, cu un sistem de digă."},{"id":"E","text":"Acul Kerr și electrozii nu trebuie să atingă obturațiile de amalgam sau coroanele metalice."}],"correct":["C","D","E"],"pages":[135],"source":"set-2"},{"id":"set2-yh_ZakiB","fingerprint":"a2d06c3d0dc05b58","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În cadrul determinării lungimii de lucru prin metoda radiologică, unde ar trebui să fie poziționat vârful acului pentru o acuratețe optimă?","options":[{"id":"A","text":"Exact la nivelul apexului radiologic."},{"id":"B","text":"La aproximativ 1 mm de apexul radiologic."},{"id":"C","text":"La o distanță de 0-2 mm coronar de apexul radiologic."},{"id":"D","text":"La 0,5 mm de apexul radiologic."},{"id":"E","text":"La nivelul foramenului apical vizibil radiografic."}],"correct":["B"],"pages":[135],"source":"set-2"},{"id":"set2-Zmp1nrnM","fingerprint":"008dcc8c0091b25e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce metodă oferă cea mai mare acuratețe în determinarea lungimii de lucru endodontice?","options":[{"id":"A","text":"Realizarea unei radiografii retroalveolare cu acul în canal."},{"id":"B","text":"Combinarea metodei electronice cu cea radiologică."},{"id":"C","text":"Măsurarea lungimii estimate pe radiografia preoperatorie."},{"id":"D","text":"Utilizarea exclusivă a unui apex locator de generația a șasea."},{"id":"E","text":"Senzația tactilă a operatorului la atingerea constricției apicale."}],"correct":["B"],"pages":[135],"source":"set-2"},{"id":"set2-7hEmCEPh","fingerprint":"4e22c8d62b542ab9","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce indică umezirea vârfului unui con de hârtie la îndepărtarea acestuia din canal, în timpul manevrei de uscare?","options":[{"id":"A","text":"Atingerea constricției apicale."},{"id":"B","text":"Uscarea completă a canalului radicular."},{"id":"C","text":"Depășirea foramenului apical."},{"id":"D","text":"Depășirea constricției apicale"},{"id":"E","text":"Prezența unui canal lateral neinstrumentat."}],"correct":["C"],"pages":[136],"source":"set-2"},{"id":"set2-a7EleaGx","fingerprint":"89800164c5a6f4fe","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este secvența corectă a mișcărilor în tehnica manuală a forțelor balansate, după ce acul întâlnește rezistență în canal?","options":[{"id":"A","text":"Mișcări axiale de dute-vino, urmate de o rotație de 360° la retragere."},{"id":"B","text":"Rotație 90° orar cu o ușoară presiune apicală, urmată de o rotație minim 90° antiorar cu presiune axială."},{"id":"C","text":"Rotație 90° antiorar, urmată de o rotație 90° orar cu presiune axială."},{"id":"D","text":"Rotație antiorară de 270 de grade este indicată pentru toate tipurile de canale."},{"id":"E","text":"Rotație continuă de 360° în sens orar pentru a avansa în canal."}],"correct":["B"],"pages":[136],"source":"set-2"},{"id":"set2-ufKSiIfo","fingerprint":"3e07dcd411e3cd7b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații referitoare la tehnica forțelor balansate sunt adevărate?","options":[{"id":"A","text":"Lărgirea canalului pe lungimea de lucru se finalizează la un diametru cu cel puțin 2 numere mai mare decât cel apical inițial."},{"id":"B","text":"Este indicată utilizarea acelor de tip Kerr cu secțiune transversală triunghiulară."},{"id":"C","text":"Alternanța între cele două rotații poziționează instrumentul în axul canalului, chiar și în prezența curburilor."},{"id":"D","text":"Precurbarea acelor este recomandată în toate canalele cu curbură."},{"id":"E","text":"Rotația în sens antiorar se realizează fără presiune axială, pentru a permite acului să se retragă."}],"correct":["A","B","C"],"pages":[136],"source":"set-2"},{"id":"set2-c-fjOqPY","fingerprint":"fd5a70264d674aec","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce definește tehnica de telescopare regresivă (step-back)?","options":[{"id":"A","text":"Scăderea lungimii de lucru a instrumentului pe măsură ce diametrul acestuia crește."},{"id":"B","text":"Utilizarea exclusivă a acelor Hedström pentru a obține o formă conică."},{"id":"C","text":"Menținerea constantă a lungimii de lucru pentru toate instrumentele utilizate."},{"id":"D","text":"Finisarea apicală se realizează întotdeauna cu acul care a determinat diametrul apical inițial."},{"id":"E","text":"Creșterea lungimii de lucru pe măsură ce diametrul instrumentului crește."}],"correct":["A"],"pages":[136],"source":"set-2"},{"id":"set2-KDFtEsQa","fingerprint":"91eaca69159cb2d1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform tehnicii de telescopare regresivă (step-back), ce conicitate se obține printr-o scurtare a lungimii de lucru cu 0,5 mm pentru fiecare ac cu diametru succesiv?","options":[{"id":"A","text":"15%"},{"id":"B","text":"20%"},{"id":"C","text":"2%"},{"id":"D","text":"5%"},{"id":"E","text":"10%"}],"correct":["E"],"pages":[136],"source":"set-2"},{"id":"set2-_Oh5yK5q","fingerprint":"be5c6fbc01158dbc","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele aspecte sunt specifice tehnicii de telescopare regresivă (step-back)?","options":[{"id":"A","text":"Mișcarea imprimată acelor este axială, de dute-vino."},{"id":"B","text":"Finisarea apicală implică instrumentarea foramenului cu un ac Kerr 20 sau 25."},{"id":"C","text":"Instrumentele lucrează mai mult pe peretele intern al rădăcinii în canalele curbe."},{"id":"D","text":"Permeabilitatea apicală se verifică cu un ac Kerr 10 sau 15 între utilizarea instrumentelor succesive."},{"id":"E","text":"În canalele curbe, instrumentele nu necesită precurbare."}],"correct":["A","B","D"],"pages":[136],"source":"set-2"},{"id":"set2-y-Cp71XO","fingerprint":"caf0b447c7519854","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform definiției, când se consideră că a fost realizată o cale de alunecare (\"glide path\")?","options":[{"id":"A","text":"Când instrumentele rotative din Ni-Ti pot să alunece ușor până la limita apicală stabilită prin odontometrie."},{"id":"B","text":"Când permeabilitatea canalului este verificată inițial și se poate pătrunde cu un ac Kerr 10."},{"id":"C","text":"Când un ac Kerr 15 poate ajunge la foramen fără să fie precurbat."},{"id":"D","text":"Atunci când este finalizată preevazarea coronară cu instrumente de conicitate mare."},{"id":"E","text":"Când un ac Kerr 10 poate să înainteze liber, ușor, pe toată lungimea de lucru, într-un mod repetat și predictibil."}],"correct":["E"],"pages":[137],"source":"set-2"},{"id":"set2-hsrq-4ok","fingerprint":"15009ecb1e8e3bed","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele sunt avantaje ale realizării unei căi de alunecare (\"glide path\")?","options":[{"id":"A","text":"Scade frecvența apariției durerilor postoperatorii și a duratei acestora."},{"id":"B","text":"Permite utilizarea în siguranță a instrumentelor rotative din nichel-titan, reducând riscul de fractură al acestora."},{"id":"C","text":"Crește durata de viață a instrumentelor utilizate pentru instrumentarea canalului."},{"id":"D","text":"Previne transportul foramenului apical în cazul utilizării instrumentelor rotative."},{"id":"E","text":"Elimină necesitatea irigării canalului radicular între pașii de instrumentare."}],"correct":["A","B","C"],"pages":[137],"source":"set-2"},{"id":"set2-Bo8tnycF","fingerprint":"73031517601567c2","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce complicații pot apărea la realizarea manuală a căii de alunecare în canalele curbe, utilizând ace de oțel inoxidabil?","options":[{"id":"A","text":"Producerea de praguri."},{"id":"B","text":"Transportul foramenului apical."},{"id":"C","text":"Crearea de perforații."},{"id":"D","text":"Reducerea duratei de viață a instrumentelor."},{"id":"E","text":"Creșterea frecvenței durerilor postoperatorii."}],"correct":["A","B","C"],"pages":[137],"source":"set-2"},{"id":"set2-XPqmPJK5","fingerprint":"49dfd575055c08da","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile specifice ale instrumentelor din sistemul PathFile?","options":[{"id":"A","text":"Sunt utilizate la o viteză de 300 rot/min și un cuplu de până la 5 Ncm."},{"id":"B","text":"Secvența de utilizare include instrumentele Path File 1 (mov, 0.13 mm), Path File 2 (alb, 0.16 mm) și Path File 3 (galben, 0.19 mm)."},{"id":"C","text":"Prezintă secțiune pătrată și conicitate constantă."},{"id":"D","text":"Sunt fabricate din aliaj de NiTi tratat termic de tip M-wire."},{"id":"E","text":"Au o conicitate variabilă, progresiv crescătoare spre mâner."}],"correct":["A","B","C"],"pages":[137],"source":"set-2"},{"id":"set2-hrEWzo1i","fingerprint":"da719ab101b99f05","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce caracteristică distinctivă aparține instrumentului ProGlider?","options":[{"id":"A","text":"O conicitate constantă de 3% și un diametru la vârf de 0.14 mm."},{"id":"B","text":"Utilizarea într-o secvență de trei instrumente de culori diferite."},{"id":"C","text":"Utilizarea la o viteză de 400 rot/min și un cuplu de 2,5 Ncm."},{"id":"D","text":"O secțiune pătrată și o lungime a părții active de 16 mm."},{"id":"E","text":"O conicitate variabilă progresiv crescătoare de la 2% la vârf la 8% spre mâner."}],"correct":["E"],"pages":[137],"source":"set-2"},{"id":"set2-qlihH0gh","fingerprint":"573908110492a417","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect instrumentul One G?","options":[{"id":"A","text":"Este realizat din aliaj de NiTi tratat termic de tip M-wire."},{"id":"B","text":"Prezintă o secțiune triunghiulară asimetrică cu 3 laturi tăietoare."},{"id":"C","text":"Are o conicitate constantă de 3% și un diametru la vârf de 0.14 mm."},{"id":"D","text":"Se utilizează la o viteză de 400 rot/min și un cuplu de 2,5 Ncm."},{"id":"E","text":"Necesită utilizarea în mișcări de pensulare (brushing) pentru a avansa."}],"correct":["B","C","D"],"pages":[137],"source":"set-2"},{"id":"set2-0Gia2hJ_","fingerprint":"de3a181655410d28","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce procedură este necesară imediat înainte de a utiliza un sistem rotativ pentru realizarea căii de alunecare?","options":[{"id":"A","text":"Lărgirea manuală a canalului până la un ac Kerr de diametru 20."},{"id":"B","text":"Confirmarea lărgirii cu un ac de 15 care ajunge la foramen fără a fi precurbat."},{"id":"C","text":"Efectuarea unei irigări abundente cu hipoclorit de sodiu pentru eliminarea detritusului."},{"id":"D","text":"Realizarea unei preevazări coronare cu instrumente de conicitate mare."},{"id":"E","text":"Verificarea permeabilității canalului cu un ac de tip Kerr 10, care trebuie să pătrundă cu ușurință pe toată lungimea de lucru."}],"correct":["E"],"pages":[137],"source":"set-2"},{"id":"set2-h8_7l45p","fingerprint":"5d6720b60a558494","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele aliajului de nichel titan de tip T-Wire, tratat termic, utilizat în sistemul de instrumentare 2 Shape?","options":[{"id":"A","text":"Rezistență crescută la oboseala ciclică"},{"id":"B","text":"Scăderea riscului de apariție a microfisurilor prin tratament termic"},{"id":"C","text":"reducerea forțelor de fricțiune în timpul instrumentării"},{"id":"D","text":"Flexibilitate îmbunătățită a instrumentelor"},{"id":"E","text":"Eficiență sporită în tăierea dentinei datorită tratamentului termic"}],"correct":["A","D"],"pages":[138],"source":"set-2"},{"id":"set2-AUw4OXrT","fingerprint":"22317f61d9a27493","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect secțiunea transversală a instrumentelor din sistemul 2 Shape și avantajele sale?","options":[{"id":"A","text":"Forma secțiunii este de triplă elice asimetrică."},{"id":"B","text":"Reduce riscul de fractură a instrumentelor endodontice."},{"id":"C","text":"Crește rezistența la oboseala ciclică a aliajului."},{"id":"D","text":"Asigură un spațiu mai mare pentru eliminarea eficientă a resturilor dentinare."},{"id":"E","text":"Prezintă trei lamele tăietoare de dimensiuni egale pentru o acțiune echilibrată."}],"correct":["A","B","D"],"pages":[138],"source":"set-2"},{"id":"set2-2EizKin0","fingerprint":"234cf3ff66979c76","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce caracteristici tehnice corespund instrumentului TS1 din sistemul 2 Shape?","options":[{"id":"A","text":"Diametru la vârf 0,40 mm, conicitate 6%"},{"id":"B","text":"Diametru la vârf 0,25 mm, conicitate 4%"},{"id":"C","text":"Diametru la vârf 0,10 mm, conicitate 2%"},{"id":"D","text":"Diametru la vârf 0,35 mm, conicitate 6%"},{"id":"E","text":"Diametru la vârf 0,25 mm, conicitate 6%"}],"correct":["B"],"pages":[138],"source":"set-2"},{"id":"set2-r_cI0c4R","fingerprint":"d9d3e45926b31eb0","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În ce situație clinică este indicată utilizarea instrumentelor de finisare F35 și/sau F40 din sistemul 2 Shape?","options":[{"id":"A","text":"Pentru lărgirea treimii coronare a canalului radicular, la începutul tratamentului."},{"id":"B","text":"Pentru realizarea căii de alunecare (glide path) înainte de instrumentarea propriu-zisă."},{"id":"C","text":"În toate cazurile, ca etapă finală obligatorie după instrumentarea cu TS1 și TS2."},{"id":"D","text":"Când un ac Kerr 25 întâmpină fricțiune la nivelul lungimii de lucru."},{"id":"E","text":"Când, după utilizarea TS2, un ac Kerr 25 introdus la lungimea de lucru se mișcă liber."}],"correct":["E"],"pages":[138],"source":"set-2"},{"id":"set2-0AuVHtAs","fingerprint":"4ff790ed4f10e7ef","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este tehnica de utilizare a instrumentelor rotative din sistemul 2 Shape în interiorul canalului radicular?","options":[{"id":"A","text":"Pătrunderea în canal până la apariția rezistenței, urmată de retragere completă și irigare."},{"id":"B","text":"Mișcări reciproce, alternând rotația în sens orar cu cea în sens antiorar."},{"id":"C","text":"Mișcări axiale continue de du-te-vino, cu o mișcare de periere pe pereții opuși curburii la retragere."},{"id":"D","text":"O singură mișcare de avansare lentă și continuă până la atingerea lungimii de lucru."},{"id":"E","text":"Mișcări de periere aplicate pe toți pereții canalului în mod egal, atât la inserție, cât și la retragere."}],"correct":["C"],"pages":[138],"source":"set-2"},{"id":"set2-h97iqDhR","fingerprint":"b93dfbcab9f61a2b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform protocolului de lucru pentru sistemul 2 Shape, când se consideră încheiată prepararea canalului radicular?","options":[{"id":"A","text":"Când un ac Kerr de mărimea 25 se mișcă liber la lungimea de lucru."},{"id":"B","text":"După utilizarea obligatorie a întregii secvențe, inclusiv a instrumentelor F35 și F40."},{"id":"C","text":"Imediat după ce instrumentul TS2 a ajuns la lungimea de lucru."},{"id":"D","text":"Atunci când un ac Kerr de mărimea 25, introdus la lungimea de lucru, prezintă fricțiune."},{"id":"E","text":"Când un ac Kerr de mărimea 10 verifică permeabilitatea apicală după irigare."}],"correct":["D"],"pages":[138],"source":"set-2"},{"id":"set2-zZ7TcLAc","fingerprint":"59e819016a12ca6a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce reprezintă secvența de bază a sistemului 2 Shape, utilizată pentru instrumentarea și modelarea formei canalului?","options":[{"id":"A","text":"Instrumentele F35 și F40"},{"id":"B","text":"Un ac Kerr 10 și un ac Kerr 25"},{"id":"C","text":"Instrumentele TS1 și F35"},{"id":"D","text":"Instrumentele One Flare și One G"},{"id":"E","text":"Instrumentele TS1 și TS2"}],"correct":["E"],"pages":[138],"source":"set-2"},{"id":"set2-_TlNXIMr","fingerprint":"d38434165f10c054","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile de design ale instrumentelor din sistemul ProTaper Next?","options":[{"id":"A","text":"Mișcarea instrumentului în canal este descrisă ca fiind \"șerpuită\" (\"swagger\")."},{"id":"B","text":"Sunt confecționate din aliaj de NiTi de tip M-wire, ceea ce le conferă o flexibilitate și o rezistență crescută la oboseala ciclică."},{"id":"C","text":"Secțiunea transversală este dreptunghiulară și simetrică față de axul de rotație al instrumentului."},{"id":"D","text":"Centrul circumferinței cercului de rotație coincide cu centrul geometric al instrumentului."},{"id":"E","text":"Toate cele patru vârfuri ale lamelelor tăietoare contactează simultan pereții canalului în timpul rotației."}],"correct":["A","B"],"pages":[139],"source":"set-2"},{"id":"set2-HjVV7YUW","fingerprint":"5a8c4bf2291b090c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce avantaje rezultă din designul specific al instrumentelor ProTaper Next, cum ar fi secțiunea asimetrică și mișcarea \"șerpuită\"?","options":[{"id":"A","text":"Contactul redus al instrumentului cu pereții canalului duce la o scădere a torsiunii exercitate asupra sa."},{"id":"B","text":"Rotația imprimă instrumentului o anvelopă de acțiune transversală mai mică decât diametrul său."},{"id":"C","text":"Spațiul mai mare între instrument și pereții canalului facilitează evacuarea detritusului dentinar."},{"id":"D","text":"Creșterea rezistenței la fractură a instrumentului."},{"id":"E","text":"Creșterea contactului instrumentului cu pereții canalului pentru o curățare mai eficientă."}],"correct":["A","C","D"],"pages":[139],"source":"set-2"},{"id":"set2-fRUJC_Lz","fingerprint":"5ecf056dc1825376","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este asocierea corectă între instrumentul ProTaper Next și caracteristicile sale tehnice?","options":[{"id":"A","text":"X2: diametru la vârf de 0,25 mm, conicitate de 7%, inel de identificare roșu."},{"id":"B","text":"X5: diametru la vârf de 0,50 mm, conicitate de 7%, două inele galbene."},{"id":"C","text":"X1: diametru la vârf de 0,17 mm, conicitate de 4%, inel de identificare galben."},{"id":"D","text":"X4: diametru la vârf de 0,40 mm, conicitate de 7%, două inele negre."},{"id":"E","text":"X3: diametru la vârf de 0,30 mm, conicitate de 6%, inel de identificare albastru."}],"correct":["C"],"pages":[139],"source":"set-2"},{"id":"set2-o9wlPk5B","fingerprint":"bbca5d2ef5bd645c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce tip de conicitate prezintă instrumentele din sistemul ProTaper Next?","options":[{"id":"A","text":"Instrumentele X1 și X2 au o conicitate progresiv crescătoare-descrescătoare."},{"id":"B","text":"Toate cele cinci instrumente ale sistemului au o conicitate constantă de-a lungul părții active."},{"id":"C","text":"Instrumentele X1 și X2 au o conicitate progresiv descrescătoare, în timp ce X3, X4 și X5 au o conicitate progresiv crescătoare-descrescătoare."},{"id":"D","text":"Instrumentele X3, X4 și X5 sunt utilizate pentru prepararea apicală dacă diametrul este superior celui al instrumentului X2."},{"id":"E","text":"Instrumentele X3, X4 și X5 au o conicitate progresiv descrescătoare."}],"correct":["A","E"],"pages":[139],"source":"set-2"},{"id":"set2-5jg2mBVI","fingerprint":"679f75cb5e0620ed","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Conform protocolului de lucru pentru sistemul ProTaper Next, care este secvența corectă de acțiuni după realizarea căii de alunecare (Glide path)?","options":[{"id":"A","text":"Se utilizează instrumentul X1 pe toată lungimea de lucru, apoi instrumentul X2 pe toată lungimea de lucru."},{"id":"B","text":"Se utilizează instrumentul X2, apoi instrumentul X1, ambele pe toată lungimea de lucru."},{"id":"C","text":"Realizarea căii de alunecare se face cu instrumentele sistemului ProTaper Next X1 și X2."},{"id":"D","text":"Se utilizează instrumentele X3, X4 sau X5 pentru lărgirea treimii apicale, indiferent de diametrul canalului."},{"id":"E","text":"Irigarea și verificarea permeabilității foramenului cu acul tip Kerr 10 se efectuează doar la finalul procedurii."}],"correct":["A"],"pages":[139],"source":"set-2"},{"id":"set2-01k3JsZC","fingerprint":"a335f6df18ff735e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile mișcării de rotație reciprocă utilizate de sistemele de tip \"single file\"?","options":[{"id":"A","text":"Se bazează pe mișcări de rotație alternative orare și antiorare de amplitudini diferite."},{"id":"B","text":"Unul dintre avantaje este reducerea oboselii ciclice a instrumentelor."},{"id":"C","text":"Amplitudinile mișcărilor de rotație în ambele sensuri sunt egale pentru a menține echilibrul."},{"id":"D","text":"Mișcarea de tăiere a dentinei (în sens antiorar) este mult mai amplă decât cea de dezangajare (în sens orar)."},{"id":"E","text":"Reprezintă o transpunere a tehnicii de instrumentare manuală a forțelor balansate (echilibrate)."}],"correct":["A","B","D","E"],"pages":[139],"source":"set-2"},{"id":"set2-d1xgbz5N","fingerprint":"2d19e7f78981b572","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Referitor la sistemele de instrumentare cu mișcare de rotație reciprocă, care dintre următoarele afirmații este corectă?","options":[{"id":"A","text":"Sistemul WaveOne a apărut înaintea sistemului Reciproc."},{"id":"B","text":"Utilizarea mișcării de reciprocitate crește riscul de fractură al instrumentelor prin acumularea oboselii ciclice."},{"id":"C","text":"Unghiul de rotație este identic pentru toate sistemele care utilizează acest tip de mișcare."},{"id":"D","text":"Sistemele Reciproc și WaveOne sunt confecționate din aliaj de nichel-titan M-wire."},{"id":"E","text":"Conceptul a fost aplicat după publicarea unui studiu în 2008 care a utilizat un instrument ProTaper Universal F2 în mișcare reciprocă."}],"correct":["D","E"],"pages":[139],"source":"set-2"},{"id":"set2-noyvGHd9","fingerprint":"3df9306a62a39104","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele utilizării mișcării de reciprocitate în prepararea canalelor radiculare?","options":[{"id":"A","text":"Reducerea timpului necesar pentru prepararea canalului radicular."},{"id":"B","text":"Permiterea resterilizării instrumentelor datorită stabilității termice a aliajului."},{"id":"C","text":"Reducerea oboselii ciclice a instrumentelor și scăderea riscului de fractură."},{"id":"D","text":"Eliminarea efectului de autoînșurubare (aspirare) a instrumentului în canal."},{"id":"E","text":"Creșterea flexibilității instrumentului cu 80% comparativ cu sistemele rotative convenționale."}],"correct":["A","C","D"],"pages":[140],"source":"set-2"},{"id":"set2-PpxgMcNi","fingerprint":"171bead52be67593","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Ce caracteristici tehnice definesc instrumentul WaveOne Gold Primary?","options":[{"id":"A","text":"Este proiectat pentru a instrumenta aproximativ 50% dintre canalele radiculare."},{"id":"B","text":"Are un inel de culoare roșie, un diametru la vârf de 0.25 mm și o conicitate de 7%."},{"id":"C","text":"Are un inel de culoare galbenă, un diametru la vârf de 0.20 mm și o conicitate de 7%."},{"id":"D","text":"Este realizat dintr-un aliaj de nichel-titan care nu a fost tratat termic."},{"id":"E","text":"Este primul instrument utilizat în canalele radiculare subțiri."}],"correct":["B"],"pages":[140],"source":"set-2"},{"id":"set2-da1cJLsD","fingerprint":"b8cba21b8a34ac44","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Din ce motiv instrumentele endodontice descrise ca fiind de tip “single use” nu pot fi resterilizate și refolosite?","options":[{"id":"A","text":"Pentru că se fracturează garantat la a doua utilizare, conform specificațiilor producătorului."},{"id":"B","text":"Din cauza măririi dimensiunii inelului colorat de pe mâner în urma sterilizării."},{"id":"C","text":"Pentru că vârful semiactiv devine complet inactiv după prima utilizare."},{"id":"D","text":"Datorită degradării termice a aliajului de nichel-titan, care își pierde flexibilitatea."},{"id":"E","text":"Deoarece secțiunea transversală în formă de paralelogram se deformează permanent."}],"correct":["B"],"pages":[140],"source":"set-2"},{"id":"set2-9_uXcouK","fingerprint":"a476dd502191a87f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la proprietățile și designul instrumentelor din sistemul WaveOne Gold?","options":[{"id":"A","text":"Au o flexibilitate cu 80% mai mare și o rezistență la oboseala ciclică cu 50% superioară față de sistemul WaveOne."},{"id":"B","text":"Sunt realizate din aliaj de nichel-titan tratat termic."},{"id":"C","text":"Sistemul conține 3 instrumente: Small, Primary și Medium."},{"id":"D","text":"Secțiunea transversală are formă de paralelogram, permițând contactul simultan al tuturor lamelor tăietoare cu pereții canalului."},{"id":"E","text":"Vârful instrumentelor este semiactiv, având o formă ogivală, conică rotunjită."}],"correct":["A","B","E"],"pages":[140],"source":"set-2"},{"id":"set2-MdTmLe1U","fingerprint":"433188448a9d9adb","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este secvența de mișcare a unui instrument WaveOne Gold în canalul radicular?","options":[{"id":"A","text":"O rotație de 150 de grade în sens orar pentru tăiere, urmată de o rotație de 30 de grade în sens antiorar pentru dezangajare."},{"id":"B","text":"O rotație de 150 de grade în sens antiorar pentru tăiere, urmată de o rotație de 30 de grade în sens orar pentru dezangajare."},{"id":"C","text":"O rotație de 120 de grade în sens antiorar pentru tăiere, urmată de o rotație de 30 de grade în sens orar pentru dezangajare."},{"id":"D","text":"O rotație de 30 de grade în sens antiorar, urmată de o rotație de 150 de grade în sens orar."},{"id":"E","text":"O rotație completă de 360 de grade este realizată după fiecare ciclu tăietor."}],"correct":["B"],"pages":[140],"source":"set-2"},{"id":"set2-huOV8kBI","fingerprint":"d84c96d40ab7229a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce aspecte caracterizează protocolul de lucru pentru instrumentarea cu sistemul WaveOne Gold?","options":[{"id":"A","text":"Mișcările de pensulare a pereților sunt indicate în toate treimile canalului radicular pentru o curățare optimă."},{"id":"B","text":"Instrumentul Primary este de obicei primul utilizat, fiind adecvat pentru aproximativ 80% dintre canale."},{"id":"C","text":"În canalele subțiri, primul instrument ales este WaveOne Gold Small."},{"id":"D","text":"Instrumentarea și modelarea canalului se realizează în absența irigantului pentru a îmbunătăți vizibilitatea."},{"id":"E","text":"Calea de alunecare trebuie realizată exclusiv cu instrumente manuale de tip Kerr pilă."}],"correct":["B","C"],"pages":[140],"source":"set-2"},{"id":"set2-y4nJVg7n","fingerprint":"6fb1246133d53b2b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce beneficii aduce forma secțiunii transversale de paralelogram a instrumentelor WaveOne Gold?","options":[{"id":"A","text":"Conferă vârfului instrumentului o formă ogivală, conică și rotunjită pentru siguranță."},{"id":"B","text":"Asigură o înaintare netă în canal de 120 de grade după fiecare ciclu tăietor."},{"id":"C","text":"Permite existența unui spațiu liber mai mare între instrument și pereții canalului, favorizând eliminarea detritusului."},{"id":"D","text":"Reduce solicitările exercitate asupra instrumentului, deoarece o singură lamelă tăietoare contactează pereții."},{"id":"E","text":"Scade riscul de blocare a instrumentului în canal."}],"correct":["C","D","E"],"pages":[140],"source":"set-2"},{"id":"set2-nf3oUT3l","fingerprint":"15f3aafb4ac609c2","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care instrument din sistemul WaveOne Gold are un diametru la vârf de 0.35 mm și o conicitate de 6%?","options":[{"id":"A","text":"Small (inel galben)"},{"id":"B","text":"Glider (inel mov)"},{"id":"C","text":"Large (inel alb)"},{"id":"D","text":"Medium (inel verde)"},{"id":"E","text":"Primary (inel roșu)"}],"correct":["D"],"pages":[140],"source":"set-2"},{"id":"set2-nyG34erW","fingerprint":"f10ef4e3ebfabdb2","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este secvența corectă a primilor pași în tratamentul endodontic după crearea cavității de acces?","options":[{"id":"A","text":"Crearea căii de alunecare, urmată de determinarea lungimii de lucru și instrumentarea cu WaveOne Gold Primary."},{"id":"B","text":"Instrumentarea cu WaveOne Gold Primary în treimea coronară, urmată de crearea căii de alunecare."},{"id":"C","text":"Determinarea lungimii de lucru cu un ac Kerr 25, urmată de negocierea canalului cu un gel chelator."},{"id":"D","text":"Se realizează o cale de alunecare utilizând instrumentul Small, după care se determină lungimea de lucru."},{"id":"E","text":"Verificarea permeabilității cu ac Kerr 10 și determinarea lungimii de lucru, urmată de crearea căii de alunecare."}],"correct":["E"],"pages":[141],"source":"set-2"},{"id":"set2-XfdK37GJ","fingerprint":"006039d309132ae4","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații referitoare la utilizarea instrumentului WaveOne Gold Primary sunt corecte?","options":[{"id":"A","text":"Utilizează mișcări de du-te - vino combinate cu mișcări de periere a pereților în treimile coronară și medie."},{"id":"B","text":"Dacă spirele sale la vârf nu sunt încărcate de dentină la atingerea lungimii de lucru, instrumentarea este considerată finalizată."},{"id":"C","text":"După îndepărtarea instrumentului din cauza blocajului, se continuă imediat cu instrumentul de dimensiune mai mare, Medium."},{"id":"D","text":"Mișcările de periere (pensulare) sunt indicate pe toată lungimea canalului, inclusiv în treimea apicală."},{"id":"E","text":"Instrumentul se îndepărtează din canal după 3 mișcări de du-te - vino sau la apariția unei senzații de blocaj."}],"correct":["A","E"],"pages":[141],"source":"set-2"},{"id":"set2-FWlG_rYx","fingerprint":"a347990bfecd1311","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În ce situație este indicată utilizarea instrumentului WaveOne Gold Small înaintea celui Primary?","options":[{"id":"A","text":"Pentru verificarea permeabilității finale a canalului, în locul acului Kerr 25."},{"id":"B","text":"Atunci când instrumentul WaveOne Gold Primary nu poate să înainteze în canalul radicular."},{"id":"C","text":"În toate cazurile dificile, ca primă intenție, pentru a preveni blocarea instrumentului Primary."},{"id":"D","text":"Atunci când se dorește lărgirea foramenului apical după finalizarea instrumentării cu Primary."},{"id":"E","text":"În cazul canalelor cu curburi accentuate, ca instrument principal pentru crearea căii de alunecare."}],"correct":["B"],"pages":[141],"source":"set-2"},{"id":"set2-NgZYrra6","fingerprint":"cf30abc8eb1f4866","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Cum se confirmă finalizarea instrumentării canalului radicular?","options":[{"id":"A","text":"Când se obține o cale de alunecare netedă, confirmată cu instrumentul WaveOne Gold Glider."},{"id":"B","text":"Prin fixarea unui ac tip Kerr 10 pe toată lungimea de lucru, fără posibilitatea de a-l mișca."},{"id":"C","text":"Prin fixarea unui ac tip Kerr 25 în canal la introducerea pe toată lungimea de lucru."},{"id":"D","text":"Prin încărcarea cu dentină a spirelor de la vârful instrumentului WaveOne Gold Primary la atingerea lungimii de lucru."},{"id":"E","text":"Atunci când instrumentul WaveOne Gold Large pătrunde cu ușurință pe toată lungimea de lucru."}],"correct":["C","D"],"pages":[141],"source":"set-2"},{"id":"set2-kl8P0Oxa","fingerprint":"cf2f5aa2f6fcc2f6","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care este procedura recomandată în cazul unui canal dificil, unde permeabilizarea inițială nu se poate realiza până la foramen?","options":[{"id":"A","text":"Se abandonează instrumentarea reciprocantă și se trece la o tehnică manuală standard cu ace Kerr."},{"id":"B","text":"Se reia faza de permeabilizare până la foramen după ce s-a instrumentat până la nivelul negociat inițial."},{"id":"C","text":"Se realizează calea de alunecare și se instrumentează cu WaveOne Gold Primary doar până la nivelul la care s-a negociat canalul."},{"id":"D","text":"Se lărgește canalul în treimea coronară cu instrumentele Medium și Large, apoi se reia permeabilizarea."},{"id":"E","text":"Se utilizează instrumentul WaveOne Gold Small pentru a forța trecerea până la foramen, apoi se instrumentează cu Primary."}],"correct":["B","C"],"pages":[141],"source":"set-2"},{"id":"set2-zUCjgjXC","fingerprint":"eb4d1ee813f273f1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele utilizării sistemului de digă în tratamentul endodontic?","options":[{"id":"A","text":"Elimină contactul pacientului cu substanțele iritante utilizate în timpul tratamentului"},{"id":"B","text":"Reduce timpul alocat tratamentului prin eliminarea definitivă a necesității de reconstrucție coronară prealabilă"},{"id":"C","text":"Asigură retracția țesuturilor moi, incluzând buzele, limba și obrajii"},{"id":"D","text":"Previne aspirarea sau ingestia instrumentarului și a altor corpi străini"},{"id":"E","text":"Reduce contrastul de culoare dintre folie și țesuturile dentare pentru a evita oboseala oculară a operatorului"}],"correct":["A","C","D"],"pages":[123],"source":"set-2"},{"id":"set2-OKHJAGsz","fingerprint":"a9e9c00a0813337c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În ce situații clinice sau afecțiuni generale este contraindicată aplicarea sistemului de digă clasic?","options":[{"id":"A","text":"Pacienții care necesită aplicarea clemei pe un premolar cu coroana clinică integră"},{"id":"B","text":"Pacienții diagnosticați cu afecțiuni cardiovasculare severe"},{"id":"C","text":"Pacienții ce prezintă edentații parțiale intercalate în cadranul izolat"},{"id":"D","text":"Pacienții care prezintă respirație orală sau astm bronșic"},{"id":"E","text":"Pacienții care prezintă un reflex de vomă exagerat la contactul cu instrumentarul"}],"correct":["D"],"pages":[123],"source":"set-2"},{"id":"set2-W0J-a9Kg","fingerprint":"dc1fc989a8fda27a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele elemente reprezintă caracteristici ale componentelor sistemului de digă?","options":[{"id":"A","text":"Pensa port-clemă are rolul de a perfora folia la diametre precis stabilite"},{"id":"B","text":"Folia de digă prezintă o formă rectangulară și o grosime cuprinsă între 0,15 și 0,35 mm"},{"id":"C","text":"Cleștele perforator de tip Ainsworth realizează orificii cu diametre diferite"},{"id":"D","text":"Cadrul sistemului de digă este confecționat exclusiv dintr-un aliaj metalic rigid"},{"id":"E","text":"Arcul sau inelul clemei se plasează întotdeauna spre mezial pentru stabilitate"}],"correct":["B","C"],"pages":[123],"source":"set-2"},{"id":"set2-GqMlJItN","fingerprint":"87e56dc70f186b1a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care sunt materialele din care sunt confecționate foliile de digă alternative destinate pacienților care prezintă alergie la latex?","options":[{"id":"A","text":"Policlorură de vinil și politetrafluoretilenă"},{"id":"B","text":"Rășini compozite fluide"},{"id":"C","text":"Elastomeri de sinteză de tip polisulfură"},{"id":"D","text":"Poliizopren sau nitril"},{"id":"E","text":"Silicon de adiție și poliuretan"}],"correct":["D"],"pages":[123],"source":"set-2"},{"id":"set2-aZURkJw-","fingerprint":"75a4d2503a450f8e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce demersuri clinice sunt menționate ca fiind necesare anterior sau în timpul aplicării sistemului de digă, în funcție de specificul cazului?","options":[{"id":"A","text":"Plasarea arcului clemei înspre aspectul mezial la pacienții ce prezintă limitarea deschiderii gurii"},{"id":"B","text":"Utilizarea cleștelui de tip Ash pentru a obține orificii de diametre variate"},{"id":"C","text":"Selectarea unei folii non-latex de poliizopren sau nitril la pacienții cu alergie la latex"},{"id":"D","text":"Realizarea unei reconstrucții temporare a pereților coronari în prezența unei distrucții majore"},{"id":"E","text":"Alocarea unui timp suplimentar pentru izolarea molarilor de minte sau a dinților în malpoziție"}],"correct":["C","D","E"],"pages":[123],"source":"set-2"},{"id":"set2-xysi3Ft2","fingerprint":"7806d703c4f70c18","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre următoarele afirmații descrie în mod adecvat protocolul de realizare și finisare a cavității de acces endodontic?","options":[{"id":"A","text":"Senzația de „cădere în gol” apare exclusiv în momentul pătrunderii prin planșeul camerei pulpare, indicând producerea unei perforații radiculare iatrogene."},{"id":"B","text":"Finisarea cavității de acces se realizează la viteză înaltă, folosind freze cu gât lung și vârf inactiv pentru a permite păstrarea morfologiei planșeului fără riscul perforării acestuia."},{"id":"C","text":"Îndepărtarea completă a tavanului camerei pulpare se efectuează la viteză înaltă, utilizând exclusiv freze sferice acționate prin mișcări de lateralitate."},{"id":"D","text":"Trepanarea camerei pulpare se realizează exclusiv cu freze din carbură de tungsten, datorită capacității lor de a produce vibrații reduse comparativ cu cele diamantate."},{"id":"E","text":"Controlul eliminării în totalitate a tavanului camerei pulpare se efectuează prin palpare tactilă cu sonda Rhein."}],"correct":["B"],"pages":[125],"source":"set-2"},{"id":"set2-jKad_Z9y","fingerprint":"a105195ff0ab2050","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile dimensionale standardizate ale instrumentarului endodontic manual convențional utilizat pentru prepararea canalelor radiculare?","options":[{"id":"A","text":"Conicitatea ISO specifică a instrumentelor convenționale din oțel inoxidabil este de 2%, fiind generată de creșterea diametrului cu 0,02 mm pentru fiecare milimetru de lungime a părții active."},{"id":"B","text":"Instrumentele cu lungimea totală de 21 mm sunt indicate în special pentru abordarea dinților laterali la pacienții cu deschidere limitată a cavității orale."},{"id":"C","text":"Diferența dintre diametrul la vârf și cel de la baza părții active este direct proporțională cu diametrul instrumentului ales."},{"id":"D","text":"Partea activă a instrumentului are o lungime constantă de 16 mm, indiferent de lungimea totală a ansamblului tijă și parte activă."},{"id":"E","text":"Diametrul la vârf este standardizat exclusiv prin valori cuprinse între 6 și 140 de zecimi de milimetru."}],"correct":["A","B","D"],"pages":[124],"source":"set-2"},{"id":"set2-ktDS4Ia4","fingerprint":"aa69f3b4c10c7d2e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Referitor la clasificarea și specificul morfologic al acelor endodontice manuale, care dintre următoarele caracteristici sunt descrise cu acuratețe?","options":[{"id":"A","text":"Acele Kerr burghiu (reamer) dispun de 24-36 de spire și o formă pătrată pe secțiune, generând o acțiune superioară de îndepărtare a dentinei comparativ cu pilele."},{"id":"B","text":"Acele Flexofile dețin o secțiune transversală de formă triunghiulară, o memorie elastică redusă și un vârf rotunjit inactiv, recomandându-le pentru tehnica forțelor compensate."},{"id":"C","text":"Acele Hedström acționează eficient și sigur prin mișcări de rotație continuă, prezentând un risc minim de fractură intradentară."},{"id":"D","text":"Acele Kerr pilă prezintă o secțiune transversală de formă pătrată, detaliu care le conferă o rezistență excelentă la torsiune și flexiune."},{"id":"E","text":"Acele K-Flex posedă o secțiune transversală în formă de romb, ceea ce le asigură o flexibilitate sporită în special la diametre mari."}],"correct":["B","D","E"],"pages":[125],"source":"set-2"},{"id":"set2-XYwu-ZSQ","fingerprint":"c02bf3dc6a4656ea","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Un medic stomatolog manevrează pe canalul radicular un instrument manual fabricat dintr-o tijă de oțel inoxidabil cu secțiune circulară, prelucrată prin tăiere astfel încât rezultă un profil de conuri suprapuse. Instrumentul este utilizat strict prin mișcări axiale de du-te-vino. Care instrument este descris și care este riscul major dictat de anatomia sa în cazul unei manipulări neadecvate?","options":[{"id":"A","text":"Acul Hedström; efectuarea oricărei mișcări de rotație atrage după sine un risc inerent de blocare și fractură a instrumentului."},{"id":"B","text":"Acul Helifile; utilizarea prin mișcări de rotație în sens antiorar provoacă înșurubarea intempestivă a acului."},{"id":"C","text":"Acul Kerr pilă; manipularea prin forțe de rotație masivă crește dramatic fenomenul de transportare a canalului apical."},{"id":"D","text":"Acul K-Flex; raclarea dentinară prin mișcări axiale pure duce la alterarea rapidă a secțiunii sale în formă de romb."},{"id":"E","text":"Acul S-file; utilizarea sa pe canale înguste blochează complet eliminarea neregularităților din treimea coronară."}],"correct":["A"],"pages":[125],"source":"set-2"},{"id":"set2-wHJiDOuO","fingerprint":"6861e6631c413a36","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Analizând evoluția conceptuală a acelor de tip Hedström (variante precum S-file, Uni-file, Helifile), care dintre următoarele trăsături definesc particularitățile acestor designuri modificate?","options":[{"id":"A","text":"Arhitectura lamelor opuse la acele S-file și Uni-file reușește să înlăture efectul de înșurubare frecvent întâlnit la acele Hedström clasice."},{"id":"B","text":"Instrumentele de tip S-file și Uni-file se caracterizează printr-un număr dublu de lame repartizate pe aceeași lungime de lucru în raport cu modelul Hedström convențional."},{"id":"C","text":"Înmulțirea lamelor pe secțiune la instrumentele Uni-file determină o fragilizare progresivă și, implicit, o scădere a rezistenței mecanice a instrumentului."},{"id":"D","text":"Secțiunea transversală a acelor S-file asigură o tăiere la fel de eficientă a dentinei indiferent dacă instrumentul este rotit în sens orar sau antiorar."},{"id":"E","text":"Acele Helifile sunt configurate geometric sub forma unei elice triple, implicând trei lame tăietoare opozante."}],"correct":["A","B","E"],"pages":[125],"source":"set-2"},{"id":"set2-EsqBPyiK","fingerprint":"67e6adabf5d69382","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile frezelor de tip Gates-Glidden utilizate în tratamentul chemo-mecanic al canalelor radiculare?","options":[{"id":"A","text":"Sunt realizate din oțel inoxidabil."},{"id":"B","text":"Se utilizează exclusiv în treimea apicală a canalului radicular."},{"id":"C","text":"Mișcarea efectuată este pasivă, circumferențială, de periere a pereților canalului."},{"id":"D","text":"Diametrul părții active este marcat prin cifre inscripționate pe mâner."},{"id":"E","text":"Partea activă prezintă 3 lame helicoidale."}],"correct":["A","C","E"],"pages":[125],"source":"set-2"},{"id":"set2-znaoyJ19","fingerprint":"90ea3f0a8cae1b8c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații referitoare la aliajul de nichel-titan utilizat în endodonție sunt corecte?","options":[{"id":"A","text":"Prezintă o compoziție de aproximativ 55% titan și 45% nichel în greutate."},{"id":"B","text":"Prezintă rezistență la coroziune și biocompatibilitate superioare oțelului inoxidabil."},{"id":"C","text":"Permite o instrumentare endodontică eficientă și predictibilă."},{"id":"D","text":"A fost propus pentru realizarea de instrumentar endodontic în anul 1988."},{"id":"E","text":"Mișcarea transmisă instrumentelor realizate din acest aliaj este exclusiv de reciprocitate."}],"correct":["B","C","D"],"pages":[125],"source":"set-2"},{"id":"set2-a5upJn2Z","fingerprint":"fe2415f2d1087e12","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Un instrument rotativ din aliaj de nichel-titan este definit de o serie de particularități proprii, printre care se numără:","options":[{"id":"A","text":"Vârful instrumentului, având un caracter exclusiv inactiv."},{"id":"B","text":"Prezența constantă a 3 lame helicoidale."},{"id":"C","text":"Aspectul și detaliile tehnice ale părții active."},{"id":"D","text":"Dimensiunile instrumentului."},{"id":"E","text":"Conicitatea."}],"correct":["C","D","E"],"pages":[126],"source":"set-2"},{"id":"set2-soypNODE","fingerprint":"92a4977fabe9886d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la fazele aliajului de nichel-titan și noile generații de instrumente endodontice?","options":[{"id":"A","text":"Aliajul R-Phase a permis realizarea unor instrumente prin tăierea sârmei de Ni-Ti, proces care le conferă rezistență la oboseala ciclică."},{"id":"B","text":"Supraelasticitatea aliajului este determinată de transformarea reversibilă dintre fazele de austenit și martensit."},{"id":"C","text":"La temperatură înaltă, aliajul se găsește în forma martensitică, caracterizându-se prin rezistență și stabilitate crescută."},{"id":"D","text":"În faza martensitică, aliajul se adaptează mai bine la solicitarea mecanică, evitându-se o creștere a tensiunii interne."},{"id":"E","text":"Instrumentele realizate din aliaj CM-wire sunt concepute să acționeze la temperatura mediului oral aflându-se în faza austenitică."}],"correct":["B","D"],"pages":[126],"source":"set-2"},{"id":"set2-TzgbToKR","fingerprint":"e883b57d2a5de7c1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt regulile clinice generale care guvernează utilizarea instrumentelor rotative din aliaj de nichel-titan?","options":[{"id":"A","text":"Viteza de rotație recomandată pentru majoritatea sistemelor din nichel-titan este cuprinsă, în general, între 250 și 600 rotații/min."},{"id":"B","text":"Prealabil utilizării instrumentelor de Ni-Ti, este necesară verificarea permeabilității canalului radicular utilizând un ac Kerr de 08 sau 10."},{"id":"C","text":"Timpul de lucru aferent unei singure introduceri în canal poate ajunge la 30 de secunde pentru a facilita îndepărtarea detritusului dentinar."},{"id":"D","text":"Mișcarea instrumentului în canalul radicular trebuie să fie continuă, în direcție corono-apicală, având o amplitudine de aproximativ 2 mm."},{"id":"E","text":"Instrumentarea mecanică se execută de preferință pe canal uscat, irigarea cu hipoclorit de sodiu realizându-se strict la finalul preparării."}],"correct":["A","B","D"],"pages":[126],"source":"set-2"},{"id":"set2-uskjOAGf","fingerprint":"aaac4fd05516cfa4","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect mecanismele și factorii care influențează riscul de fractură al instrumentelor din nichel-titan?","options":[{"id":"A","text":"Oboseala ciclică rezultă din cumularea stresului în aliaj, fiind dependentă atât de anatomia radiculară, cât și de viteza de rotație a instrumentului."},{"id":"B","text":"Riscul de fractură al instrumentelor se majorează pe măsură ce gradul de curbură al canalului crește și raza de curbură devine mai mică."},{"id":"C","text":"Instrumentele din nichel-titan sunt de patru ori mai rigide comparativ cu cele din oțel, particularitate ce favorizează fractura în treimea apicală."},{"id":"D","text":"Acumularea oboselii ciclice în masa aliajului determină o creștere compensatorie a rezistenței instrumentului la solicitarea prin torsiune."},{"id":"E","text":"Existența unei conicități constante a părții active predispune la blocarea instrumentului în cursul rotației, favorizând generarea stresului prin torsiune."}],"correct":["A","B","E"],"pages":[127],"source":"set-2"},{"id":"set2-w4L2mU3U","fingerprint":"7bd80d733177e26f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre caracteristicile specifice instrumentelor din nichel-titan contribuie direct la diminuarea numărului de instrumente necesare modelării formei canalului radicular și la scurtarea timpului de lucru?","options":[{"id":"A","text":"Efectuarea unui tratament termic de tip CM-wire care forțează instrumentul să acționeze exclusiv în faza austenitică."},{"id":"B","text":"Posibilitatea fabricării unor instrumente cu conicități variabile sau constante de-a lungul părții active, cuprinse între 2% și 12-19%."},{"id":"C","text":"Memoria de formă a materialului, capabil să revină instantaneu la configurația sa dreaptă originală consecutiv curbării apărute în timpul lucrului."},{"id":"D","text":"Flexibilitatea intrinsecă de patru ori mai mare în raport cu aliajele convenționale din oțel inoxidabil."},{"id":"E","text":"Implementarea cinemacii asimetrice, prin utilizarea lor obligatorie într-o mișcare reciprocă pe toată durata tratamentului."}],"correct":["B"],"pages":[126],"source":"set-2"},{"id":"set2-ai7FUwbu","fingerprint":"f5d0cd6fcf9b6813","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Asocierea dintre tipurile inovatoare de aliaje Ni-Ti și particularitățile instrumentelor obținute include următoarele caracteristici veridice:","options":[{"id":"A","text":"Instrumentele bazate pe aliajul R-Phase prezintă o rezistență crescută la oboseala ciclică în comparație cu sistemele convenționale obținute prin tăiere."},{"id":"B","text":"Fenomenul de supraelasticitate necesită, în mod imperativ, prezența unei proporții dominante de Ni-Ti în faza austenitică."},{"id":"C","text":"Instrumentele fabricate din aliaj CM-wire (2010) acționează la temperatura mediului oral regăsindu-se în faza martensitică."},{"id":"D","text":"Generația de instrumente din aliaj M-Wire (2007) se caracterizează printr-o flexibilitate îmbunătățită și un nivel superior de rezistență la oboseala ciclică."},{"id":"E","text":"Aliajul R-Phase impune realizarea instrumentelor endodontice prin tehnica de tăiere a sârmei, limitând flexiunea lor în canale curbe."}],"correct":["A","C","D"],"pages":[127],"source":"set-2"},{"id":"set2-3Ui5hzpN","fingerprint":"8dd246fb052c7fbc","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile finger spreaderelor și avantajele lor comparativ cu hand spreaderele?","options":[{"id":"A","text":"Îndepărtarea lor din canal riscă dislocarea frecventă a gutapercii."},{"id":"B","text":"Prezintă un mâner lung, similar celui al unei sonde dentare."},{"id":"C","text":"Permit rotirea ușoară în ambele sensuri."},{"id":"D","text":"Conferă o mai mare sensibilitate tactilă."},{"id":"E","text":"Au o parte activă cilindrică cu vârful plat."}],"correct":["C","D"],"pages":[127],"source":"set-2"},{"id":"set2-iBVXVxbB","fingerprint":"f3ce06c101b354f6","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care este descrierea morfologică și funcțională corectă a pluggerelor?","options":[{"id":"A","text":"Sunt instrumente destinate introducerii în canalul radicular a pastelor și a hidroxidului de calciu."},{"id":"B","text":"Există variante cu ambele părți active identice ca formă, dar diferite ca diametru."},{"id":"C","text":"Partea activă este cilindrică, având vârful plat."},{"id":"D","text":"Sunt utilizate pentru exercitarea unei presiuni verticale asupra gutapercii încălzite."},{"id":"E","text":"Sunt instrumente manuale destinate condensării laterale la rece a conurilor de gutapercă."}],"correct":["B","C","D"],"pages":[127],"source":"set-2"},{"id":"set2-riwmgmUT","fingerprint":"2486645169b5be7a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce caracteristici prezintă acul Lentullo din punct de vedere dimensional și al codificării culorilor?","options":[{"id":"A","text":"Inelul albastru indică un diametru fin."},{"id":"B","text":"Inelul roșu indică un diametru extrafin."},{"id":"C","text":"Inelul negru indică un diametru extrafin."},{"id":"D","text":"Există trei lungimi diferite: 17 mm, 21 mm și 25 mm."},{"id":"E","text":"Inelul verde corespunde unui diametru gros."}],"correct":["A","B","D"],"pages":[128],"source":"set-2"},{"id":"set2-w0Bd7-cu","fingerprint":"64546e5500ad8add","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la cinematica instrumentelor utilizate în obturarea canalelor radiculare?","options":[{"id":"A","text":"Acul Lentullo este utilizat prin rotație în sens antiorar."},{"id":"B","text":"Acul Lentullo se folosește prin rotație în sens orar, la viteză convențională, retrăgându-se progresiv."},{"id":"C","text":"Pluggerele execută mișcări de rotație la viteză convențională pentru introducerea sealerului."},{"id":"D","text":"Acul Lentullo depune pasta simultan cu avansarea sa spre constricția apicală."},{"id":"E","text":"Pe parcursul obturării, mișcarea realizată cu spreaderele este combinată, implicând presiune apicală, laterală și rotație."}],"correct":["B","E"],"pages":[128],"source":"set-2"},{"id":"set2-AqmbzIZZ","fingerprint":"a72dee8cd4caca82","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile fizice și de material ale spreaderelor și pluggerelor utilizate în tratamentul de canal?","options":[{"id":"A","text":"Spreaderele pot fi confecționate din oțel inoxidabil."},{"id":"B","text":"Hand spreaderele prezintă un mâner scurt, similar instrumentarului manual de lărgire a canalelor radiculare."},{"id":"C","text":"Finger spreaderele au lungimi standard de 21 sau 25 mm."},{"id":"D","text":"Aliajul de nichel-titan este utilizat pentru confecționarea acului Lentullo."},{"id":"E","text":"Pluggerele pot avea o singură parte activă sau ambele părți active."}],"correct":["A","C","E"],"pages":[127],"source":"set-2"},{"id":"set2-NswdjsL4","fingerprint":"7cdd88328787b09e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele reprezintă obiective ale realizării cavității de acces endodontic?","options":[{"id":"A","text":"Asigurarea unui acces rectiliniu al instrumentelor endodontice până la apex sau până la prima curbură a canalului radicular."},{"id":"B","text":"Obținerea unei cavități cu pereți ușor divergenți spre ocluzal ca suport pentru materialul de obturație provizorie."},{"id":"C","text":"Eliminarea parțială a țesuturilor dure dentare infectate pentru a conserva structura dentară."},{"id":"D","text":"Vizualizarea directă și identificarea tuturor orificiilor canalelor radiculare."},{"id":"E","text":"Obținerea unei cavități cu pereți ușor convergenți spre ocluzal care devine rezervor pentru soluția de irigare."}],"correct":["A","B","D"],"pages":[128],"source":"set-2"},{"id":"set2-LlzbLdZL","fingerprint":"56d04857445cb74f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt informațiile obținute prin efectuarea sondajului parodontal premergător realizării cavității de acces?","options":[{"id":"A","text":"Volumul și poziția camerei pulpare în plan radiologic."},{"id":"B","text":"Prezența unor calcificări la nivelul camerei pulpare."},{"id":"C","text":"Conturul coroanei la nivelul coletului."},{"id":"D","text":"Existența unor rădăcini suplimentare."},{"id":"E","text":"Localizarea furcației și a joncțiunii smalț-cement."}],"correct":["C","D","E"],"pages":[128],"source":"set-2"},{"id":"set2-NgQ2N1IZ","fingerprint":"82ea14fca687c493","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele etape fac parte din procesul de realizare a cavității de acces endodontic?","options":[{"id":"A","text":"Păstrarea țesuturilor dure dentare afectate în zonele profunde pentru protecția pulpară."},{"id":"B","text":"Îndepărtarea parțială a plafonului camerei pulpare pentru conservarea țesutului dentar integru."},{"id":"C","text":"Trepanarea și îndepărtarea completă a plafonului camerei pulpare."},{"id":"D","text":"Identificarea orificiilor de emergență ale canalelor radiculare."},{"id":"E","text":"Stabilirea conturului cavității de acces și trepanarea smalțului și a dentinei."}],"correct":["C","D","E"],"pages":[128],"source":"set-2"},{"id":"set2-UWhfZd3t","fingerprint":"74949d4c16ca710d","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce elemente sunt evaluate prin intermediul analizei radiologice efectuate anterior preparării cavității de acces endodontic?","options":[{"id":"A","text":"Numărul de rădăcini și de canale radiculare."},{"id":"B","text":"Curburile canalelor radiculare și lungimea lor aproximativă."},{"id":"C","text":"Axul longitudinal al canalului radicular."},{"id":"D","text":"Prezența unor materiale de obturație preexistente."},{"id":"E","text":"Conturul coroanei la nivelul coletului."}],"correct":["A","B","D"],"pages":[128],"source":"set-2"},{"id":"set2-kzucbYkS","fingerprint":"f3b77531f57247c8","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este parametrul evaluat din punct de vedere clinic ce va ghida utilizarea instrumentelor de preparare premergător realizării cavității de acces?","options":[{"id":"A","text":"Joncțiunea smalț-cement."},{"id":"B","text":"Plafonul camerei pulpare."},{"id":"C","text":"Conturul coroanei la nivelul coletului."},{"id":"D","text":"Furcația radiculară."},{"id":"E","text":"Axul longitudinal al rădăcinii."}],"correct":["E"],"pages":[128],"source":"set-2"},{"id":"set2-2xcCA8ui","fingerprint":"6b16f8621bfd4de5","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre următoarele etape descrie abordarea corectă pentru realizarea cavității de acces la dinții frontali?","options":[{"id":"A","text":"Punctul de frezaj se stabilește ușor cervical față de cingulum, pe fața orală a dintelui."},{"id":"B","text":"În cazul unei camere pulpare complet calcificate apare o senzație accentuată de \"cădere în gol\" la deschiderea acesteia."},{"id":"C","text":"După trepanarea tavanului camerei pulpare, îndepărtarea acestuia se realizează cu mișcări de avansare dinspre exterior spre interior."},{"id":"D","text":"Axa inițială de trepanare se menține paralelă cu axul longitudinal al dintelui încă de la începutul procedurii."},{"id":"E","text":"Pentru axa inițială de trepanare, freza va fi orientată perpendicular pe fața orală până la perforarea plafonului camerei pulpare."}],"correct":["E"],"pages":[128],"source":"set-2"},{"id":"set2-OOy6owvH","fingerprint":"823a5b99c9ba11b3","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile morfologice ale triunghiurilor dentinare evidențiate în timpul preparării cavității de acces la dinții frontali?","options":[{"id":"A","text":"Triunghiul dentinar cervical este situat palatinal."},{"id":"B","text":"Pentru eliminarea triunghiului cervical pot fi utilizate freze Gates-Glidden, în ordine crescătoare de la 2 la 6."},{"id":"C","text":"Triunghiul dentinar incizal este situat predominant palatinal."},{"id":"D","text":"După trepanarea tavanului camerei pulpare se pun în evidență două triunghiuri dentinare: unul incizal și altul cervical."},{"id":"E","text":"Menținerea triunghiurilor dentinare este indicată pentru a asigura ghidajul pasiv al instrumentarului în canalul radicular."}],"correct":["A","B","D"],"pages":[129],"source":"set-2"},{"id":"set2-loGiB10t","fingerprint":"50c0c5b76df76710","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt particularitățile specifice cavităților de acces la nivelul dinților frontali maxilari?","options":[{"id":"A","text":"Pentru incisivii centrali maxilari, cavitatea de acces este localizată în treimea medie a coroanei."},{"id":"B","text":"La incisivii centrali maxilari, cavitatea de acces are o formă triunghiulară rotunjită."},{"id":"C","text":"Incisivii laterali și caninii maxilari necesită o cavitate de acces ovoidală, mai largă în sens mezio-distal decât în sens cervico-incizal."},{"id":"D","text":"La incisivii laterali și caninii maxilari, poate fi necesară o extensie incizală crescută pentru un abord rectiliniu, fără interferențe."},{"id":"E","text":"La incisivii centrali maxilari, pereții cavității de acces sunt convergenți spre palatinal."}],"correct":["A","B","D"],"pages":[129],"source":"set-2"},{"id":"set2-Ja0Q74Jt","fingerprint":"50ebbf2a33c6a57f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce trăsături distinctive prezintă cavitatea de acces endodontic în cazul dinților frontali mandibulari?","options":[{"id":"A","text":"Extensia incizală a cavității este strict contraindicată din cauza fațetelor de uzură prezente frecvent la acest nivel."},{"id":"B","text":"Forma specifică a cavității de acces la acești dinți este exclusiv de tip circular."},{"id":"C","text":"O extensie corect realizată permite explorarea și accesarea canalelor radiculare vestibular și lingual, dacă acestea sunt ambele prezente."},{"id":"D","text":"Localizarea se face cu predilecție la nivelul treimii de colet a feței linguale."},{"id":"E","text":"Pereții cavității de acces sunt divergenți spre incizal."}],"correct":["C","E"],"pages":[129],"source":"set-2"},{"id":"set2-mfmUcUGE","fingerprint":"4b06ff947047cd62","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele principii tehnice sunt esențiale pentru prevenirea accidentelor iatrogene în cursul realizării cavității de acces la dinții frontali?","options":[{"id":"A","text":"Îndepărtarea tavanului camerei pulpare se execută prin mișcări de înfundare a frezei spre zona apicală, pentru un control tactil de înaltă finețe."},{"id":"B","text":"Transferul distanței măsurate radiografic pe instrumentul rotativ de trepanare ajută la prevenirea perforațiilor accidentale."},{"id":"C","text":"Păstrarea axului perpendicular pe fața orală pe toată durata preparării cavității scade considerabil riscul creării pragurilor dentinare."},{"id":"D","text":"Măsurarea distanței dintre marginea incizală și tavanul camerei pulpare pe radiografia preoperatorie constituie o metodă de referință în caz de calcificări pulpare."},{"id":"E","text":"Orientarea frezei paralel cu axul longitudinal al dintelui, după trepanarea inițială, previne riscul de perforație la nivelul pereților laterali sau vestibular."}],"correct":["B","D","E"],"pages":[128],"source":"set-2"},{"id":"set2-zON4nbL5","fingerprint":"7cab696e35b905d3","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile morfologice și ale cavității de acces endodontic în cazul premolarilor maxilari?","options":[{"id":"A","text":"Pereții laterali ai cavității de acces sunt convergenți spre ocluzal."},{"id":"B","text":"Premolarul doi maxilar este în mod constant multiradicular."},{"id":"C","text":"Camera pulpară prezintă o formă alungită în sens vestibulo-oral."},{"id":"D","text":"Forma cavității de acces este ovalară, cu axul lung vestibulo-palatinal."},{"id":"E","text":"Cavitatea de acces este mai lată în sens mezio-distal datorită aplatizării rădăcinii."}],"correct":["C","D"],"pages":[129],"source":"set-2"},{"id":"set2-EkMMZO9O","fingerprint":"5fa1daf071576c73","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu particularitățile anatomice și de acces endodontic ale premolarilor mandibulari?","options":[{"id":"A","text":"Axul lung al cavității de acces are o orientare vestibulo-linguală."},{"id":"B","text":"Cuspidul vestibular al primului premolar inferior este mult mai voluminos comparativ cu cel lingual."},{"id":"C","text":"Cavitatea de acces este ușor vestibularizată din cauza diferenței de angulație între axul coronar și cel radicular."},{"id":"D","text":"Unghiul format de axul coronar și cel radicular este deschis spre vestibular."},{"id":"E","text":"La primul premolar inferior, camera pulpară este localizată aproape în întregime sub cuspidul lingual."}],"correct":["A","B","C"],"pages":[129],"source":"set-2"},{"id":"set2-lhko0AsY","fingerprint":"0542857c85f7b437","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este tehnica adecvată și instrumentarul corespunzător pentru prepararea cavității de acces și îndepărtarea tavanului camerei pulpare la un premolar maxilar?","options":[{"id":"A","text":"Se utilizează o freză globulară activă pentru a nivela pereții axiali divergent spre ocluzal."},{"id":"B","text":"Se utilizează o freză cu vârful inactiv, de tip Endo-Z, prin mișcări de translație vestibulo-orale."},{"id":"C","text":"Frezajul inițial se realizează cu o freză orientată paralel cu fața ocluzală."},{"id":"D","text":"Tavanul camerei pulpare se îndepărtează prin mișcări de translație strict mezio-distale."},{"id":"E","text":"Se folosește o sondă 17 pentru a îndepărta plafonul prin mișcări de tracționare spre apical."}],"correct":["B"],"pages":[129],"source":"set-2"},{"id":"set2-IlDMCmBr","fingerprint":"31db82000a7583cd","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt reperele anatomice și topografice relevante în etapele inițiale ale accesului endodontic la nivelul premolarilor maxilari?","options":[{"id":"A","text":"Canalul palatinal este situat la distanță de șanțul mezio-distal, spre centrul cuspizilor."},{"id":"B","text":"Identificarea orificiilor de emergență se realizează cu ajutorul sondei 16 sau a acelor Kerr."},{"id":"C","text":"Sonda 17 este instrumentul de elecție pentru pătrunderea inițială și verificarea rectiliniarității la nivelul canalelor radiculare."},{"id":"D","text":"Punctul inițial de frezaj este situat în centrul șanțului mezio-distal."},{"id":"E","text":"Cele două canale radiculare sunt dispuse de o parte și de alta a șanțului mezio-distal, pe o direcție vestibulo-orală."}],"correct":["B","D","E"],"pages":[129],"source":"set-2"},{"id":"set2-xURJ7Eil","fingerprint":"e83250cf54c94181","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Referitor la etapele și instrumentarul utilizat pentru prepararea cavității de acces endodontic la molari, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Punctul inițial de frezaj este plasat perpendicular pe fața ocluzală, în foseta centrală."},{"id":"B","text":"Pereții axiali rezultați în urma preparării trebuie să prezinte o orientare convergentă spre ocluzal."},{"id":"C","text":"Acuratețea îndepărtării interferențelor dentinare se verifică folosind o sondă 17."},{"id":"D","text":"Direcția de acțiune a frezei în cazul molarilor inferiori trebuie să țină seama de axul de înclinare în sens vestibulo-lingual și mezio-distal."},{"id":"E","text":"Îndepărtarea completă a tavanului camerei pulpare se realizează exclusiv cu o freză sferică diamantată."}],"correct":["A","C","D"],"pages":[130],"source":"set-2"},{"id":"set2-_-c_Nny0","fingerprint":"3645d552d262798a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile anatomice și de preparare ale cavității de acces pentru molarii maxilari?","options":[{"id":"A","text":"Orificiul de emergență al celui de-al doilea canal mezio-vestibular poate fi mascat de o punte incompletă de dentină."},{"id":"B","text":"Localizarea canalelor radiculare începe în mod curent cu cel palatinal, acesta fiind mai larg și mai drept."},{"id":"C","text":"Cavitatea de acces a primului molar superior are o formă de patrulater cu unghiurile rotunjite, latura cea mai scurtă fiind cea palatinală."},{"id":"D","text":"Camera pulpară a molarului II maxilar prezintă o aplatizare pronunțată în sens vestibulo-lingual."},{"id":"E","text":"Cel de-al doilea canal mezio-vestibular este situat de obicei cu 1-2 mm mai spre vestibular față de primul canal mezio-vestibular."}],"correct":["A","B","C"],"pages":[130],"source":"set-2"},{"id":"set2-gtiOt09g","fingerprint":"7955fb39452a1518","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect morfologia și cavitatea de acces a molarilor mandibulari?","options":[{"id":"A","text":"Forma cavității de acces este de trapez, cu baza mare situată întotdeauna distal."},{"id":"B","text":"Rădăcina mezială a molarilor mandibulari prezintă în toate cazurile un singur canal radicular, situat central."},{"id":"C","text":"Cavitatea de acces ocluzală este situată cu precădere mai înspre partea distală a feței ocluzale."},{"id":"D","text":"În situația prezenței a două canale distale, baza mică a conturului trapezului ocluzal se va mări."},{"id":"E","text":"Poate exista o configurație radiculară ce include simultan două canale distale și trei canale meziale."}],"correct":["D","E"],"pages":[130],"source":"set-2"},{"id":"set2-EPhnzIxi","fingerprint":"768c9e9fa7d61592","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Referitor la anatomia camerei pulpare și cavitatea de acces a molarilor maxilari unu și doi, care dintre afirmațiile de mai jos sunt exacte?","options":[{"id":"A","text":"La molarul unu maxilar, latura mezială reprezintă porțiunea cea mai scurtă a cavității de acces."},{"id":"B","text":"La nivelul podelei camerei pulpare a molarului II maxilar, canalele pot fi situate practic pe o singură linie din cauza angulației unghiului corespunzător canalului disto-vestibular."},{"id":"C","text":"La molarul II maxilar, orificiul canalului disto-vestibular este situat mult mai spre palatinal față de poziția sa la primul molar."},{"id":"D","text":"În cazul primului molar maxilar, latura distală este cea mai lungă dintre laturile conturului patrulater."},{"id":"E","text":"Latura vestibulară a cavității de acces a primului molar superior este ușor înclinată spre palatinal."}],"correct":["B","C","E"],"pages":[130],"source":"set-2"},{"id":"set2-s78A8O_3","fingerprint":"3511e4ef10d3a656","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt instrumentele și regulile tehnice specifice utilizate în timpul preparării cavității de acces pentru molari?","options":[{"id":"A","text":"Avansarea spre camera pulpară presupune menținerea paralelismului frezei cu peretele distal al dintelui pentru a evita perforația."},{"id":"B","text":"Frezajul inițial se execută la turație convențională utilizând exclusiv instrumentar manual."},{"id":"C","text":"Îndepărtarea tavanului camerei pulpare se face cu o freză prevăzută cu vârf activ, pentru a pătrunde în podea."},{"id":"D","text":"Finisarea pereților axiali se poate realiza folosind freza Endo Acces sau anse ultrasonice."},{"id":"E","text":"Puntea incompletă de dentină care acoperă orificiul celui de-al II-lea canal mezio-vestibular se poate îndepărta prin utilizarea anselor ultrasonice."}],"correct":["D","E"],"pages":[130],"source":"set-2"},{"id":"set2-kmkauUmd","fingerprint":"f4025e02df581521","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre următoarele afirmații descriu corect incidentele ce pot apărea prin modificarea poziției și formei foramenului apical în cursul instrumentării canalelor radiculare?","options":[{"id":"A","text":"Transportul extern determină formarea unui foramen apical în formă de clepsidră exclusiv din cauza utilizării instrumentelor cu flexibilitate mare."},{"id":"B","text":"Deplasarea internă a foramenului apical se produce prin acumularea de resturi dentinare în apropierea constricției apicale."},{"id":"C","text":"Deplasarea internă a foramenului este cauzată de memoria elastică a instrumentelor, mai evidentă la vârful acestora."},{"id":"D","text":"Riscul de a produce deplasarea externă a foramenului scade odată cu utilizarea unor instrumente endodontice cu diametru tot mai mare."},{"id":"E","text":"Crearea unui prag sau o perforație apare atunci când un instrument precurbat apasă pe fața externă a curburii canalului radicular."}],"correct":["B"],"pages":[132],"source":"set-2"},{"id":"set2-Tdqu2ahl","fingerprint":"686cb7ac582dbe40","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele obținerii unei forme conice continue a canalului radicular preparat?","options":[{"id":"A","text":"Permite instrumentelor să ajungă și să instrumenteze mai ușor regiunea apicală."},{"id":"B","text":"Facilitează pătrunderea soluțiilor de lavaj endodontic."},{"id":"C","text":"Permite o obturație de canal corectă, printr-o distribuție favorabilă a forțelor în cursul realizării acesteia."},{"id":"D","text":"Elimină necesitatea utilizării unui instrument de permeabilitate apicală."},{"id":"E","text":"Transformă forma pe secțiune a canalelor ovale într-o secțiune circulară pentru a îmbunătăți eficiența lavajului."}],"correct":["A","B","C"],"pages":[132],"source":"set-2"},{"id":"set2-m7B_4_pP","fingerprint":"82729934fa483d3f","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele aspecte se numără printre obiectivele biologice ale preparării canalului radicular?","options":[{"id":"A","text":"Asigurarea contactului total al instrumentelor endodontice cu toți pereții canalului pentru a substitui necesitatea irigării activate."},{"id":"B","text":"Trecerea tuturor instrumentelor flexibile dincolo de foramenul apical este necesară pentru a asigura curățarea parodonțiului."},{"id":"C","text":"Instrumentarea canalului radicular trebuie făcută respectând țesuturile periapicale, fără extinderea în afara canalului radicular."},{"id":"D","text":"Menținerea poziției și formei originale a foramenului apical."},{"id":"E","text":"Conținutul canalului radicular, incluzând pulpa, țesutul necrotic, detritusurile și flora microbiană, trebuie eliminat în totalitate."}],"correct":["C","E"],"pages":[132],"source":"set-2"},{"id":"set2-FIku7LV8","fingerprint":"4e5df781ce2fc7f1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Pentru a menține traseul anatomic original al canalului radicular în timpul preparării, este necesar să se respecte anumite principii. Care dintre următoarele enunțuri este conform acestor principii?","options":[{"id":"A","text":"Menținerea traseului anatomic original reprezintă un obiectiv biologic fundamental al tratamentului endodontic."},{"id":"B","text":"Este important să se mențină cât mai multă dentină radiculară pentru a preveni riscul producerii perforațiilor și scăderii rezistenței pereților."},{"id":"C","text":"Îndepărtarea dentinei coronare se realizează preferențial de la nivelul pereților situați pe aceeași parte cu curbura radiculară."},{"id":"D","text":"La canalele cu secțiune transversală ovală, preparația finală trebuie să le confere o formă strict circulară."},{"id":"E","text":"Păstrarea traseului original este realizată adesea prin îndepărtarea unei cantități mai mari de dentină din treimea apicală a canalului."}],"correct":["B"],"pages":[132],"source":"set-2"},{"id":"set2-j2WxkFps","fingerprint":"0fc257c5107b0d2b","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"O serie de abordări sunt susținute în prezent privind menținerea și prepararea diametrului foramenului apical. Care dintre următoarele enunțuri descriu corect aceste concepte endodontice?","options":[{"id":"A","text":"O abordare sugerează lărgirea canalului la nivel apical cu trei numere superioare instrumentului care a determinat diametrul inițial, cu scopul de a elimina bacteriile din regiune."},{"id":"B","text":"Este indicată utilizarea unor instrumente cu dimensiunea de 0,20 mm dacă prima pătrundere cu un ac de 0,10 mm se realizează cu dificultate."},{"id":"C","text":"Motivul principal pentru menținerea diametrului foramenului apical cât mai redus este de a permite soluțiilor de irigare să ajungă în contact prelungit cu țesutul osos periapical."},{"id":"D","text":"Se recomandă menținerea diametrului apical inițial în situația în care acesta era deja mai mare decât 0,20 mm."},{"id":"E","text":"Studiile indică faptul că îndepărtarea unei cantități masive de dentină apicală este strict necesară, indiferent dacă se realizează sau nu o conicitate adecvată irigării."}],"correct":["A","B","D"],"pages":[132],"source":"set-2"},{"id":"set2-8LS77hBG","fingerprint":"16402354d874cf8e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele lărgirii preliminare a canalului radicular în cadrul tratamentului mecanic endodontic?","options":[{"id":"A","text":"Garantează contactul permanent al instrumentului endodontic cu pereții canalului pe întreaga lungime a celor trei treimi radiculare."},{"id":"B","text":"Diminuează cantitatea de resturi dentinare și floră microbiană împinse accidental în regiunea periapicală."},{"id":"C","text":"Împiedică utilizarea instrumentelor precurbate, forțând adaptarea mecanică directă a acelor drepte la nivelul treimii apicale."},{"id":"D","text":"Asigură pătrunderea mai rapidă a acului de irigare în zonele profunde, prelungind timpul de contact cu flora microbiană."},{"id":"E","text":"Permite un acces sigur și controlat la nivelul treimii apicale, însoțit de o sensibilitate tactilă superioară."}],"correct":["B","D","E"],"pages":[133],"source":"set-2"},{"id":"set2-5W7gMR_t","fingerprint":"7cb1643b160256f8","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele enunțuri descriu în mod obiectiv mișcarea de rotație reciprocă alternativă (\"watch winding\") utilizată în instrumentarea canalului radicular?","options":[{"id":"A","text":"Se utilizează doar după ce apexul a fost atins, cu scopul exclusiv de a netezi traiectoria treimii apicale."},{"id":"B","text":"Se realizează prin rotirea acului în sens orar între 30 și 60 de grade, urmată de o rotație în sens antiorar de aceeași amplitudine."},{"id":"C","text":"Presupune aplicarea unor tracțiuni liniare de 5-10 mm în axul lung al dintelui, urmate de rotație continuă."},{"id":"D","text":"Este asociată cu o incidență redusă în producerea de praguri la nivelul pereților canalului radicular."},{"id":"E","text":"Prezintă un caracter neagresiv, instrumentul propulsându-se treptat de-a lungul canalului fără a necesita o forță de împingere masivă."}],"correct":["B","D","E"],"pages":[133],"source":"set-2"},{"id":"set2-9qzxUZ-D","fingerprint":"29cfd645c02a5aa6","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce caracteristici anatomice și procedurale definesc etapa de explorare și lărgire preliminară a canalului radicular?","options":[{"id":"A","text":"Explorarea debutează prin folosirea exclusivă a instrumentarului rotativ din nichel-titan de calibru mare, omițând instrumentele manuale din oțel."},{"id":"B","text":"Lărgirea preliminară vizează instrumentarea inițială a treimii coronare și, în anumite cazuri, a celei medii, înainte de prepararea apicală."},{"id":"C","text":"La trecerea printr-o porțiune extrem de strâmtă a canalului, un ac precurbat își va accentua și menține flexiunea apicală impusă de anatomie."},{"id":"D","text":"Cele trei treimi ale canalului radicular (coronară, medie și apicală) au fiecare o lungime anatomică stabilită între 3 și 5 mm."},{"id":"E","text":"Se recomandă utilizarea inițială a unui ac Kerr cu diametrul de 8 sau 10 pentru a cerceta configurația anatomică a sistemului canalar."}],"correct":["B","D","E"],"pages":[132],"source":"set-2"},{"id":"set2-VTavBHt3","fingerprint":"fa7b5dd5528d4726","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În timpul explorării inițiale a canalului radicular, instrumentul manual Kerr nu poate înainta până la lungimea de lucru estimată pe radiografia preoperatorie. Care este tehnica indicată pentru a propulsa instrumentul în canal evitând forțarea acestuia?","options":[{"id":"A","text":"Introducerea imediată a unui sistem rotativ din nichel-titan tip PathFile sau One G pentru permeabilizarea mecanică a blocajului."},{"id":"B","text":"Imprimarea unei mișcări de rotație reciprocă alternativă în sens orar și antiorar, cu o amplitudine de 30-60 de grade."},{"id":"C","text":"Mobilizarea acului în direcție apico-coronară prin mișcări de tragere și împingere cu o amplitudine de 0,5 până la 2 mm."},{"id":"D","text":"Retragerea acului, supra-curbarea vârfului acestuia și aplicarea unei forțe axiale apicale majore până la atingerea lungimii de lucru."},{"id":"E","text":"Inversarea secvenței tehnice și prepararea imediată a porțiunii neexplorate direct cu tehnica de telescopare regresivă (step-back)."}],"correct":["B"],"pages":[133],"source":"set-2"},{"id":"set2-hKRXJRn6","fingerprint":"cf5bd01e58ca5740","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt afirmațiile adevărate privind lărgirea treimii coronare (preevazarea coronară) a canalului radicular?","options":[{"id":"A","text":"Se realizează exclusiv cu instrumente de nichel-titan de conicitate redusă."},{"id":"B","text":"Instrumentele acționează cu preponderență pe peretele radicular opus curburii rădăcinii."},{"id":"C","text":"Frezele Gates Glidden pot fi utilizate în ordine crescătoare inclusiv în porțiunea curbată a canalului radicular."},{"id":"D","text":"Lărgirea inițială cu ace Kerr pilă previne formarea de praguri la utilizarea ulterioară a frezelor Gates Glidden."},{"id":"E","text":"Unul dintre scopurile mișcării imprimate instrumentelor de preevazare este reducerea curburii treimii coronare."}],"correct":["B","D","E"],"pages":[133],"source":"set-2"},{"id":"set2-4Z2g_oVL","fingerprint":"c10487ad8fd8a03e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele reprezintă avantaje și particularități ale instrumentelor rotative de nichel-titan utilizate pentru preevazare (precum ProTaper SX sau One Flare)?","options":[{"id":"A","text":"Elimină interferențele dentinare situate la nivelul intrării în canalele radiculare."},{"id":"B","text":"Necesită aplicarea unei presiuni apicale constante în timpul instrumentării pentru a preveni deviația de la axul canalului."},{"id":"C","text":"Contribuie la diminuarea riscului de fractură a instrumentelor folosite ulterior în prepararea canalului."},{"id":"D","text":"Asigură curățarea și relocalizarea intrării în canalul radicular."},{"id":"E","text":"Prezintă o lungime mai mare pentru a asigura explorarea concomitentă a treimii apicale a canalului."}],"correct":["A","C","D"],"pages":[134],"source":"set-2"},{"id":"set2-MN-u4QPI","fingerprint":"8c32a3991403d882","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care este tehnica corectă de utilizare a instrumentarului în etapa de preevazare coronară?","options":[{"id":"A","text":"Instrumentelor rotative de nichel-titan li se imprimă o mișcare de apăsare (pensulare) pe peretele opus curburii, pe parcursul retragerii din canal."},{"id":"B","text":"Frezele Gates Glidden se activează printr-o mișcare de retragere și înclinare, exclusiv în porțiunea rectilinie a canalului."},{"id":"C","text":"În cazul canalelor meziale ale molarilor maxilari și mandibulari, peretele pe care se acționează poartă întotdeauna denumirea canalului instrumentat."},{"id":"D","text":"Acele Kerr utilizate inițial se acționează predominant pe peretele situat de aceeași parte cu curbura rădăcinii."},{"id":"E","text":"Se evită irigarea canalului pe parcursul etapei incipiente de lărgire cu ace Kerr pentru a menține forța de adeziune a rumegușului dentinar."}],"correct":["A","B","C"],"pages":[133],"source":"set-2"},{"id":"set2-wd5ZQpXO","fingerprint":"7453f12b3dddfbcb","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este motivul principal pentru care instrumentele rotative de nichel-titan cu conicitate mare, utilizate în preevazarea coronară, trebuie manevrate fără presiune apicală?","options":[{"id":"A","text":"Avansarea forțată scurtează prematur lungimea de lucru a canalului radicular, producând un stop apical fals."},{"id":"B","text":"Aplicarea presiunii apicale în timpul rotației predispune la formarea de praguri la nivelul pereților dentinari."},{"id":"C","text":"O presiune crescută în axul dintelui determină creșterea exponențială a flexibilității aliajului, anulând astfel capacitatea sa de tăiere."},{"id":"D","text":"Presiunea apicală transmisă instrumentului generează invariabil un sindrom de dinte fisurat pe parcursul intervenției."},{"id":"E","text":"Presiunea apicală blochează funcția de rotație a motorului endodontic."}],"correct":["B"],"pages":[134],"source":"set-2"},{"id":"set2-1szkvK9Y","fingerprint":"ddd6b14f081d6f54","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Cum se calculează lungimea estimativă a canalului radicular înainte de etapa de permeabilizare?","options":[{"id":"A","text":"Prin avansarea pasivă a acului până la perceperea tactilă a constricției apicale în treimea apicală."},{"id":"B","text":"Prin utilizarea directă a apex locatorului înainte de lărgirea treimii coronare și mediene."},{"id":"C","text":"Prin măsurarea distanței dintre foramenul apical și un reper coronar, din care se scade 0,5 mm."},{"id":"D","text":"Prin măsurarea distanței dintre apexul radiologic și constricția apicală, la care se adaugă 1 mm."},{"id":"E","text":"Prin măsurarea distanței dintre apexul radiologic al dintelui și un reper situat pe marginea incizală sau fața ocluzală, din care se scade 1 mm."}],"correct":["E"],"pages":[134],"source":"set-2"},{"id":"set2-fQS4UjY8","fingerprint":"f6217906849546e5","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt tehnicile și manevrele adecvate utilizate pentru sondarea permeabilității canalului radicular?","options":[{"id":"A","text":"Efectuarea unor mișcări de rotație reciprocă în sens orar și antiorar (watch winding)."},{"id":"B","text":"Precurbarea acului la vârf și rotarea lui cu o ușoară presiune în cazul unei curburi importante apicale."},{"id":"C","text":"Lărgirea prealabilă a treimii apicale prin mișcări axiale înainte de introducerea acelor fine pentru negociere."},{"id":"D","text":"Executarea unor mișcări axiale de mare amplitudine pentru avansarea rapidă dincolo de treimea medie."},{"id":"E","text":"Utilizarea unor ace fine de dimensiuni reduse, de calibru 6, 8 sau 10."}],"correct":["A","B","E"],"pages":[134],"source":"set-2"},{"id":"set2-x5WJbPxF","fingerprint":"f7a5c802349079ba","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este procedura indicată imediat după permeabilizarea foramenului pentru a lărgi ușor zona apicală?","options":[{"id":"A","text":"Menținerea fixă a acului la lungimea de lucru estimativă pe toată durata etapei de evaluare radiologică."},{"id":"B","text":"Executarea unor mișcări de rotație continuă de mare amplitudine fără utilizarea soluțiilor de irigare."},{"id":"C","text":"Retragerea imediată a acului și reluarea lărgirii exclusiv în treimea coronară și medie."},{"id":"D","text":"Executarea unor mișcări axiale de mică amplitudine, între 0,5 și 2 mm, însoțite de irigare."},{"id":"E","text":"Avansarea acului cu 3 până la 4 mm dincolo de foramenul apical pentru confirmarea permeabilității depline."}],"correct":["D"],"pages":[134],"source":"set-2"},{"id":"set2-kobA02Ta","fingerprint":"78d97b71233e74fb","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce elemente definesc protocolul și caracteristicile permeabilizării canalului radicular?","options":[{"id":"A","text":"Procedura de permeabilizare începe obligatoriu cu lărgirea întregului sistem endodontic, de la orificiu până la constricția apicală."},{"id":"B","text":"Mișcările axiale de mică amplitudine se repetă până când acul se mișcă liber în interiorul canalului."},{"id":"C","text":"Acele de dimensiuni reduse, conduse pasiv în canal, vin în contact cu pereții radiculari exclusiv în treimea apicală."},{"id":"D","text":"Negocierea se realizează până la foramenul apical, urmată de depășirea acestuia cu 0,5-1 mm."},{"id":"E","text":"Verificarea finală a poziției acului se realizează exclusiv radiologic, evitând utilizarea apex locatorului."}],"correct":["B","C","D"],"pages":[134],"source":"set-2"},{"id":"set2-DClsBKaJ","fingerprint":"5c0d77feb403f747","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre următoarele afirmații este adevărată în ceea ce privește constricția apicală?","options":[{"id":"A","text":"Distanța dintre constricția apicală și foramenul apical este o constantă de 1 mm pe tot parcursul vieții pacientului."},{"id":"B","text":"Se prezintă exclusiv sub forma unui trunchi de con, având baza mare la nivelul constricției și baza mică la foramenul apical."},{"id":"C","text":"Constituie o limită strict histologică, poziția sa situându-se invariabil la niveluri diferite ale pereților parietali din același canal."},{"id":"D","text":"Reprezintă zona cu diametrul transversal cel mai mic, fiind considerată limita optimă a instrumentării și obturării canalului radicular."},{"id":"E","text":"Distanța dintre constricția apicală și apexul anatomic este o valoare fixă de 0,5 mm la toți dinții."}],"correct":["D"],"pages":[135],"source":"set-2"},{"id":"set2-p4J-enq7","fingerprint":"80e1c3a387b66b3a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Din punct de vedere al formei, care sunt tipurile de constricții apicale descrise în anatomia endodontică?","options":[{"id":"A","text":"Multiple constricții situate apical."},{"id":"B","text":"Aspect convențional, sub formă de trunchi de con cu baza mică la constricție și cea mare la foramen."},{"id":"C","text":"Constricție cu aspect sferic localizată la nivelul joncțiunii cemento-dentinare."},{"id":"D","text":"Formă paralelă, pe o distanță limitată la maximum 0,5 mm în zona apicală."},{"id":"E","text":"Formă conică."}],"correct":["A","B","E"],"pages":[135],"source":"set-2"},{"id":"set2-imTXpgQ9","fingerprint":"3215f9a227fd5272","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Pentru determinarea corectă a lungimii de lucru prin metoda electronică, este necesară respectarea anumitor condiții. Care dintre următoarele afirmații descrie o practică sau o regulă precisă?","options":[{"id":"A","text":"Din lungimea măsurată la care aparatul indică atingerea ligamentului periodontal se scade 0,5 mm pentru obținerea lungimii de lucru."},{"id":"B","text":"Izolarea dintelui este opțională dacă pacientul prezintă o cantitate redusă de salivă în cavitatea orală."},{"id":"C","text":"Electrozii și acul endodontic pot intra în contact cu obturațiile de amalgam, însă nu și cu coroanele metalice."},{"id":"D","text":"Progresia mișcării acului pe ecranul aparatului corespunde întotdeauna perfect cu mișcarea fizică a acestuia în canalul radicular."},{"id":"E","text":"Diametrul acului endodontic utilizat nu influențează măsurătoarea, indiferent de dimensiunea canalului radicular."}],"correct":["A"],"pages":[135],"source":"set-2"},{"id":"set2-yQxdzuyO","fingerprint":"b3785f4065bfc04c","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu reperele și distanțele caracteristice anatomiei regiunii apicale?","options":[{"id":"A","text":"Distanța dintre foramenul apical și constricția apicală variază între 0,2 mm și 0,6 mm, fiind mai mare la tineri în comparație cu vârstnicii."},{"id":"B","text":"Joncțiunea cemento-dentinară reprezintă o limită histologică ce se află întotdeauna la același nivel transversal în interiorul aceluiași canal radicular."},{"id":"C","text":"Foramenul apical poate fi situat la o distanță cuprinsă între 0 și 2 mm coronar de apexul anatomic."},{"id":"D","text":"Apexul radiologic constituie imaginea radiologică a punctului terminus al rădăcinii dintelui."},{"id":"E","text":"Distanța medie dintre constricția apicală și apexul anatomic la incisivii inferiori este de aproximativ 0,79 mm."}],"correct":["C","D","E"],"pages":[135],"source":"set-2"},{"id":"set2-7pseMdam","fingerprint":"870ff564f0aa4763","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Ce aspecte caracterizează metodele de determinare și verificare a lungimii de lucru?","options":[{"id":"A","text":"Umezirea vârfului unui con de hârtie introdus în canal, consecutiv uscării acestuia, indică depășirea foramenului apical."},{"id":"B","text":"Ajustarea vârfului acului pe radiografie trebuie făcută exact la nivelul apexului radiologic pentru o instrumentare corectă."},{"id":"C","text":"Acuratețea cea mai mare în determinarea lungimii de lucru se obține prin combinarea metodelor electronică și radiologică."},{"id":"D","text":"Acuratețea maximă în stabilirea lungimii de lucru se obține prin utilizarea exclusivă a apex locatorului."},{"id":"E","text":"Apex locatoarele de generația a șasea utilizează aprecierea modificării impedanței dintre doi electrozi pentru a detecta apropierea de ligamentul periodontal."}],"correct":["A","C","E"],"pages":[135],"source":"set-2"},{"id":"set2-xG0kG9Rs","fingerprint":"c915d5dc84d0b263","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este succesiunea exactă a mișcărilor și a forțelor aplicate în instrumentarea manuală prin tehnica forțelor balansate?","options":[{"id":"A","text":"Rotație orară de 90 de grade, urmată de retragerea acului 1 mm din canal și reluarea mișcării în sens antiorar."},{"id":"B","text":"Rotație completă orară de 360 de grade cu presiune apicală, urmată de mișcări axiale de du-te-vino și retragere."},{"id":"C","text":"Pătrundere pasivă, rotație antiorară de 90 de grade cu tracțiune, urmată de rotație orară de 270 de grade cu presiune axială."},{"id":"D","text":"Rotație orară de 90 de grade cu ușoară presiune apicală, urmată de rotație antiorară de minimum 90 de grade cu presiune axială, urmată de rotație orară de 360 de grade cu retragerea acului."},{"id":"E","text":"Rotație orară de 90 de grade fără presiune, urmată de rotație antiorară de 270 de grade cu presiune axială, urmată de rotație orară de 180 de grade însoțită de retragere."}],"correct":["D"],"pages":[136],"source":"set-2"},{"id":"set2-2WMhK6gC","fingerprint":"368ce55418f80e64","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile procedurale ale tehnicii de telescopare regresivă (step-back)?","options":[{"id":"A","text":"În situația instrumentării canalelor curbe, acele precurbate vor acționa într-o proporție mai mare pe peretele intern al curburii radiculare."},{"id":"B","text":"Se bazează pe principiul scăderii lungimii de lucru la care acționează instrumentul concomitent cu creșterea diametrului acestuia."},{"id":"C","text":"Trecerea de la un instrument de un anumit diametru la cel următor implică obligatoriu irigarea canalului și verificarea permeabilității apicale cu un ac Kerr 10 sau 15."},{"id":"D","text":"Mișcarea imprimată acelor de tip Kerr pilă și Hedström este una de tip axial, de du-te-vino, acționând la nivelul pereților canalului radicular."},{"id":"E","text":"Obținerea unei conicități continue a canalului de 10% se realizează prin scurtarea lungimii de lucru cu 1 mm pentru fiecare ac față de instrumentul precedent."}],"correct":["B","C","D"],"pages":[136],"source":"set-2"},{"id":"set2-H-kIbQHF","fingerprint":"36c03ec0b323f90a","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care dintre următoarele ansambluri de caracteristici tehnice descrie cu exactitate instrumentul ProGlider, utilizat pentru prepararea rotativă a căii de alunecare?","options":[{"id":"A","text":"Diametrul la vârf de 0,14 mm, conicitate constantă de 3% și secțiune transversală triunghiulară asimetrică."},{"id":"B","text":"Secțiune pătrată, conicitate constantă, vârf rotunjit inactiv și lungime a părții active de 16 mm."},{"id":"C","text":"Inel de culoare albă pe mâner, diametrul la vârf de 0,16 mm, lungimea părții active de 18 mm și conicitate variabilă progresiv crescătoare de la 2% la 8%."},{"id":"D","text":"Diametrul la vârf de 0,16 mm, inel de culoare albă pe mâner, utilizare la o viteză de 400 rot/min și un cuplu de 2,5 Ncm."},{"id":"E","text":"Diametrul la vârf de 0,19 mm, conicitate constantă și inel de identificare de culoare galbenă pe mâner."}],"correct":["C"],"pages":[137],"source":"set-2"},{"id":"set2-CNPpjxFv","fingerprint":"4602f56a3a37fe69","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt avantajele clinice și tehnice ale creării căii de alunecare (glide path) anterior instrumentării rotative din nichel titan?","options":[{"id":"A","text":"Crește probabilitatea apariției pragurilor și perforațiilor radiculare în anatomia complexă a canalelor curbe."},{"id":"B","text":"Asigură respectarea fidelă a traiectoriei canalelor radiculare, chiar și în prezența unor curburi anatomice accentuate."},{"id":"C","text":"Contribuie la prelungirea duratei de viață a instrumentelor endodontice utilizate ulterior pentru instrumentarea propriu-zisă a canalului."},{"id":"D","text":"Determină o creștere semnificativă a timpului de lucru alocat etapei de instrumentare endodontică."},{"id":"E","text":"Induce o scădere a frecvenței de apariție a durerilor postoperatorii, precum și a duratei de manifestare a acestora."}],"correct":["B","C","E"],"pages":[137],"source":"set-2"},{"id":"set2-y22EqOO9","fingerprint":"3a93862b2607f613","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Referitor la parametrii și etapele tehnicii forțelor balansate și a stabilirii diametrului apical inițial, care dintre următoarele afirmații sunt documentate medical?","options":[{"id":"A","text":"Precurbarea instrumentelor înaintea introducerii în canal este obligatorie pentru absolut toate topografiile radiculare."},{"id":"B","text":"Este indicată exclusiv utilizarea acelor de tip Kerr care prezintă o secțiune transversală pătrată, pentru a le oferi o rezistență superioară la stresul de torsiune."},{"id":"C","text":"Lărgirea canalului pe lungimea de lucru se va finaliza cu un ac al cărui diametru trebuie să fie cu cel puțin 2 numere mai mare comparativ cu diametrul apical inițial."},{"id":"D","text":"Instrumentarea curburilor mici sau a celor generalizate pe toată lungimea radiculară impune o mișcare de rotație antiorară de 270 de grade în a doua etapă a tehnicii."},{"id":"E","text":"Diametrul apical inițial se stabilește cu primul ac introdus pasiv, fără niciun efort de instrumentare, care manifestă fricțiune la nivelul constricției apicale."}],"correct":["C","D","E"],"pages":[136],"source":"set-2"},{"id":"set2-EU1P2j6c","fingerprint":"04a3806309f7ddf6","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt caracteristicile sistemelor de instrumentare rotativă cu mișcare continuă 2 Shape și ProTaper Next?","options":[{"id":"A","text":"Mișcarea șerpuită a instrumentelor ProTaper Next este determinată de coincidența centrului circumferinței cercului de rotație cu cel al instrumentului."},{"id":"B","text":"Sistemul ProTaper Next prezintă o secțiune transversală dreptunghiulară, asimetrică față de axul de rotație."},{"id":"C","text":"Forma secțiunii transversale a instrumentelor 2 Shape este de triplă elice asimetrică."},{"id":"D","text":"Instrumentele sistemului 2 Shape sunt supuse unei depuneri electrolitice după frezare pentru a scădea riscul apariției microfisurilor de suprafață."},{"id":"E","text":"Sistemul 2 Shape este confecționat din aliaj de nichel-titan de tip M-wire tratat termic."}],"correct":["B","C","D"],"pages":[138],"source":"set-2"},{"id":"set2-ISxVtJR3","fingerprint":"1879ca0fcb2c4304","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"În ceea ce privește secvența și protocolul de lucru pentru sistemul 2 Shape, care dintre următoarele elemente tehnice este valid?","options":[{"id":"A","text":"Instrumentul TS1 prezintă un diametru la vârf de 0,25 mm și o conicitate de 4%."},{"id":"B","text":"Realizarea căii de alunecare se realizează cu instrumentele PathFile sau ProGlider."},{"id":"C","text":"Instrumentul TS2 are un diametru la vârf de 0,25 mm și o conicitate de 4%."},{"id":"D","text":"Secvența de finisare apicală cu instrumentele F35 sau F40 se utilizează exclusiv dacă acul de tip Kerr 25 prezintă fricțiune la lungimea de lucru."},{"id":"E","text":"Mișcarea de retragere din canalul radicular implică o mișcare de periere direcționată în special spre pereții dinspre curbura canalului."}],"correct":["A"],"pages":[138],"source":"set-2"},{"id":"set2-tGpePKpq","fingerprint":"2db916517c347062","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt particularitățile dimensionale și structurale ale instrumentelor din sistemul ProTaper Next?","options":[{"id":"A","text":"Instrumentele opționale X3, X4 și X5 au o conicitate progresiv crescătoare."},{"id":"B","text":"Instrumentele X1 și X2 au o conicitate progresiv crescătoare-descrescătoare de-a lungul părții active."},{"id":"C","text":"Torsiunea exercitată asupra instrumentului este redusă ca urmare a contactului redus cu pereții canalului."},{"id":"D","text":"Instrumentul X3 este identificat prin inelul de culoare albastră și prezintă un diametru la vârf de 0,30 mm cu o conicitate de 7%."},{"id":"E","text":"Instrumentul X4 se identifică printr-un singur inel negru și prezintă un diametru la vârf de 0,40 mm."}],"correct":["B","C","D"],"pages":[139],"source":"set-2"},{"id":"set2-tv_6L-3A","fingerprint":"7f658d807eed1e34","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Identificați caracteristica precisă a sistemelor de preparare mecanică a canalelor radiculare:","options":[{"id":"A","text":"Sistemul 2 Shape se caracterizează prin instrumente care prezintă o mișcare „șerpuită” denumită „swagger”."},{"id":"B","text":"Aliajul T-Wire utilizat pentru confecționarea instrumentelor ProTaper Next le conferă acestora flexibilitate superioară."},{"id":"C","text":"Instrumentul F40 din sistemul 2 Shape prezintă un diametru la vârf de 0,40 mm și o conicitate de 4%."},{"id":"D","text":"Lărgirea treimii coronare în protocolul sistemului ProTaper Next se realizează cu instrumentul One Flare."},{"id":"E","text":"Instrumentul X2 al sistemului ProTaper Next este marcat cu un inel roșu, având un diametru la vârf de 0,25 mm și conicitate de 6%."}],"correct":["E"],"pages":[139],"source":"set-2"},{"id":"set2-8XTzBD3f","fingerprint":"216236e68b206719","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Avantajele formei asimetrice a secțiunii transversale de triplă elice la instrumentele din sistemul 2 Shape sunt reprezentate de:","options":[{"id":"A","text":"Crearea unui spațiu mai mic între pereții canalului și suprafața instrumentului pentru creșterea eficienței tăierii."},{"id":"B","text":"Reducerea forțelor de fricțiune care acționează asupra instrumentului."},{"id":"C","text":"Asigurarea unui spațiu mai mare care permite eliminarea resturilor dentinare din canal."},{"id":"D","text":"Reducerea riscului de fractură al instrumentelor."},{"id":"E","text":"Atingerea pereților canalului cu doar două dintre cele patru vârfuri ale lamelelor tăietoare."}],"correct":["B","C","D"],"pages":[138],"source":"set-2"},{"id":"set2-PXbZP4uA","fingerprint":"e5840c0ac00932ed","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele caracteristici descriu instrumentele componente ale sistemului WaveOne Gold?","options":[{"id":"A","text":"Instrumentele prezintă flexibilitate cu 50% mai mare și rezistență la oboseala ciclică cu 80% superioară față de generația anterioară."},{"id":"B","text":"Vârful instrumentelor este complet activ și are o formă cilindrică tăietoare."},{"id":"C","text":"Instrumentul Large prezintă inel alb, diametru la vârf de 0.345 mm și conicitate de 6%."},{"id":"D","text":"Instrumentul Primary prezintă inel roșu, diametru la vârf de 0.25 mm și conicitate de 7%."},{"id":"E","text":"Secțiunea transversală are formă de paralelogram, permițând contactul simultan al tuturor lamelelor tăietoare cu pereții canalului."}],"correct":["C","D"],"pages":[140],"source":"set-2"},{"id":"set2-ExR7pJwm","fingerprint":"aaeb3ef458bb5fd8","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Care este dinamica exactă a mișcării de rotație reciprocă a instrumentelor WaveOne Gold în interiorul canalului radicular?","options":[{"id":"A","text":"Înaintarea netă în canal după finalizarea completă a trei cicluri tăietoare este de 120 de grade."},{"id":"B","text":"Tăierea dentinei se realizează exclusiv prin mișcarea de retragere axială, nu prin mișcarea de rotație."},{"id":"C","text":"Rotația în sens antiorar este de 150 de grade, urmată de o rotație de dezangajare în sens orar de 30 de grade."},{"id":"D","text":"Rotația alternativă se produce cu unghiuri perfect egale, anulând efectul de aspirare a instrumentului."},{"id":"E","text":"Mișcarea se bazează pe o rotație de 150 de grade în sens orar, urmată de 30 de grade în sens antiorar."}],"correct":["C"],"pages":[140],"source":"set-2"},{"id":"set2-Q6tfcxvT","fingerprint":"c17771977fb265a1","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care sunt pașii și regulile recomandate în protocolul de instrumentare cu sistemul WaveOne Gold Primary?","options":[{"id":"A","text":"Instrumentarea se efectuează prin mișcări de du-te-vino combinate cu mișcări de periere a pereților radiculari pe toată lungimea de lucru a canalului."},{"id":"B","text":"Mișcările de pensulare a pereților canalului radicular sunt interzise în treimea apicală."},{"id":"C","text":"Instrumentul WaveOne Gold Primary trebuie utilizat întotdeauna ca prim instrument, indiferent de dimensiunea inițială a canalului radicular."},{"id":"D","text":"După executarea a 3 mișcări de du-te-vino sau la apariția senzației de blocaj, instrumentul se retrage pentru irigarea și reverificarea permeabilității canalului."},{"id":"E","text":"Confirmarea instrumentării apicale se poate realiza utilizând un ac tip Kerr 25 care se fixează în canal la introducerea pe toată lungimea de lucru."}],"correct":["B","D","E"],"pages":[141],"source":"set-2"},{"id":"set2-iALbxNa2","fingerprint":"1fcc17ac90a8aeed","chapterId":"set-2","subchapterId":"set2-2.03","type":"CS","text":"Resterilizarea instrumentarului din sistemele de rotație reciprocă prevăzute cu design „single use” este împiedicată din punct de vedere fizic de:","options":[{"id":"A","text":"Pierderea ireversibilă a conicității prin expansiunea termică tridimensională a aliajului Ni-Ti utilizat la fabricarea instrumentului."},{"id":"B","text":"Distrugerea proprietăților de flexibilitate ale aliajului M-wire în autoclav, ducând la fracturarea imediată a tijei metalice."},{"id":"C","text":"Ștergerea marcajelor de adâncime de pe tija din aliaj nichel-titan, care împiedică ulterior controlul exact al lungimii de lucru."},{"id":"D","text":"Modificarea structurală a lamelei tăietoare unice, care capătă o formă complet netedă sub acțiunea căldurii excesive."},{"id":"E","text":"Mărirea în dimensiune a inelului colorat de la nivelul mânerului în timpul procesului de sterilizare, care blochează reintroducerea în piesa de endodonție."}],"correct":["E"],"pages":[140],"source":"set-2"},{"id":"set2-8k_OA6Ay","fingerprint":"e8959ed51f6bf78e","chapterId":"set-2","subchapterId":"set2-2.03","type":"CM","text":"Care dintre următoarele afirmații descriu conduita adecvată în prepararea canalelor radiculare dificile, strâmte sau cu curburi accentuate, conform protocolului tehnic general?","options":[{"id":"A","text":"Faza de permeabilizare și crearea căii de alunecare până la foramen se reiau după ce a fost instrumentată prima porțiune negociată a canalului."},{"id":"B","text":"Calea de alunecare se realizează până la nivelul de negociere al canalului, fiind urmată de lărgirea cu WaveOne Gold Primary strict până la acel nivel."},{"id":"C","text":"Mișcările de pensulare ample aplicate curburilor accentuate din treimea apicală sunt obligatorii pentru lărgirea și netezirea optimă a acestor zone dificile."},{"id":"D","text":"Instrumentul WaveOne Gold Small poate fi utilizat pentru a pătrunde de mai multe ori pe lungimea de lucru atunci când instrumentul Primary întâmpină dificultăți de avansare."},{"id":"E","text":"Se continuă obligatoriu forțarea instrumentului WaveOne Gold Primary pe toată lungimea, pentru a depăși zona de strâmtoare radiculară și a asigura permeabilitatea."}],"correct":["A","B","D"],"pages":[141],"source":"set-2"}];
